/**
 * TİLTOPİA — "KEDİ KAPI: KULE TIRMANIŞI" v8.0
 * src/door.js — 5 Benzersiz Kapı Mekanizması, Kilitli Zemin Mimarisi & Fiziksel Güvenlik
 * Konsorsiyum: Mert (Fizik & Kule), Selin (Görsel Tasarım & UI), Burak (Çarpışma & Platform)
 */

function distToSegmentSq(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const l2 = dx * dx + dy * dy;
  if (l2 === 0) return (px - x1) * (px - x1) + (py - y1) * (py - y1);
  let t = ((px - x1) * dx + (py - y1) * dy) / l2;
  t = Math.max(0, Math.min(1, t));
  const qx = x1 + t * dx;
  const qy = y1 + t * dy;
  return (px - qx) * (px - qx) + (py - qy) * (py - qy);
}

class FloorDoor {
  constructor(floorNumber, y, spec, config = CONFIG) {
    this.floorNumber = floorNumber;
    this.y = y;
    this.spec = spec;
    this.config = config;

    this.width = spec.doorWidth;
    this.height = config.DOOR_HEIGHT;
    this.centerX = config.CANVAS_WIDTH / 2;
    const halfSpan = (spec.mechanic === "ROTATING_FAN") ? (spec.fanRadius || 64) : this.width / 2;
    this.leftPostX = this.centerX - halfSpan;
    this.rightPostX = this.centerX + halfSpan;

    this.cycleLength = spec.cycleLength;
    this.openDuration = spec.openDuration;
    this.cycleTimer = 0;

    // Durum Değişkenleri
    this.isOpen = false;
    this.isSnapping = false;
    this.isWarning = false;
    this.wasOpenOnCatEntry = false;
    this.snapSoundPlayed = false;
    this.impactRattle = 0;
    this.isSealed = false; // Kat geçilince alt zemin tamamen mühürlenir

    // 1. & 3. Aşama: Sarkaç & Giyotin Açısı
    this.flapAngle = 0;
    this.targetFlapAngle = 0;

    // 2. Aşama: Dönen Havalandırma Çarkı
    this.fanAngle = 0;
    this.hasCollidedBlade = false;

    // 4. Aşama: Sekme Pedi & Fırtına Sundurması
    this.bouncerX = spec.bouncerX || 416;
    this.bouncerYOffset = (spec.bouncerYOffset !== undefined) ? spec.bouncerYOffset : 90;
    this.bouncerH = spec.bouncerH || 180;
    this.bouncerHitTimer = 0;
    this.hasBouncedThisLaunch = false;
    this.canopyW = spec.canopyW || 295;
    this.canopyH = spec.canopyH || 22;
    this.canopyYOffset = (spec.canopyYOffset !== undefined) ? spec.canopyYOffset : 190;

    // 5. Aşama: İris Diyafram Açıklığı
    this.irisRadius = 0;
    this.irisMaxR = spec.irisMaxR || 44;

    this.glowLeft = 0;
    this.glowRight = 0;

    // Kat taban kotu
    this.platformY = config.GROUND_Y - (floorNumber - 1) * config.FLOOR_HEIGHT;
  }

  sealFloor() {
    this.isSealed = true;
    this.isOpen = false;
    this.hasCollidedBlade = false;
    this.hasBouncedThisLaunch = false;
    this.targetFlapAngle = 0;
    this.flapAngle = 0;
  }

  applyImpactShudder(intensity = 1.0) {
    this.impactRattle = 0.28 * intensity;
    this.glowLeft = 1.0;
    this.glowRight = 1.0;
  }

  update(dt, audio = null, particles = null, isCurrentFloor = true) {
    // Geçilmiş alt katlar tamamen dondurulur (Sıfır ses, sıfır hareket, sıfır gürültü)
    if (this.isSealed && !isCurrentFloor) return;

    this.cycleTimer = (this.cycleTimer + dt) % this.cycleLength;
    const progress = this.cycleTimer / this.cycleLength;

    if (this.bouncerHitTimer > 0) {
      this.bouncerHitTimer = Math.max(0, this.bouncerHitTimer - dt);
    }

    // -------------------------------------------------------------
    // MEKANİZMA 2: DÖNEN KANATLI HAVALANDIRMA ÇARKI (ROTATING_FAN)
    // -------------------------------------------------------------
    if (this.spec.mechanic === "ROTATING_FAN") {
      this.fanAngle = (this.fanAngle + (this.spec.fanSpeed || 1.25) * dt) % (Math.PI * 2);
      const bladeHalf = (this.spec.bladeAngle || 0.28) / 2; // ~0.14 rad
      // Kırmızı kapalı olma eşiği: ~0.48 rad (~27.5°). Kırmızı kapalı kalma oranı %44'e çıkarıldı.
      const entryCorridorThreshold = bladeHalf + 0.34; // ~0.48 rad
      let minEntryDiff = Math.PI;
      for (let b = 0; b < 3; b++) {
        const bAngle = (this.fanAngle + (b * Math.PI * 2) / 3) % (Math.PI * 2);
        // Alt giriş ekseni: PI / 2 (Aşağıdan yukarıya dikey geçiş)
        const diff = Math.abs((((bAngle - Math.PI / 2) + Math.PI) % (Math.PI * 2)) - Math.PI);
        if (diff < minEntryDiff) minEntryDiff = diff;
      }

      this.isOpen = (minEntryDiff > entryCorridorThreshold);
      this.isWarning = (minEntryDiff > entryCorridorThreshold && minEntryDiff <= entryCorridorThreshold + 0.14);
      this.isSnapping = (minEntryDiff <= entryCorridorThreshold);
      return;
    }

    // -------------------------------------------------------------
    // MEKANİZMA 3: RAYDA KAYAN YATAY LAZER GİYOTİNİ (SLIDING_GUILLOTINE)
    // -------------------------------------------------------------
    if (this.spec.mechanic === "SLIDING_GUILLOTINE") {
      const offset = Math.sin(this.cycleTimer * (this.spec.slideSpeed || 2.20)) * (this.spec.slideAmp || 62);
      this.centerX = this.config.CANVAS_WIDTH / 2 + offset;
      this.leftPostX = this.centerX - this.width / 2;
      this.rightPostX = this.centerX + this.width / 2;

      // Kapı merkez eksendeyken açık; orantılı daraltılmış tolerans (|offset| < 28px)
      this.isOpen = (Math.abs(offset) < 28);
      this.isWarning = (Math.abs(offset) >= 28 && Math.abs(offset) < 38);
      this.isSnapping = (Math.abs(offset) >= 38);
      this.targetFlapAngle = Math.PI / 2.2;
      this.flapAngle = this.targetFlapAngle;
      return;
    } else {
      this.centerX = this.config.CANVAS_WIDTH / 2;
      this.leftPostX = this.centerX - this.width / 2;
      this.rightPostX = this.centerX + this.width / 2;
    }

    // -------------------------------------------------------------
    // MEKANİZMA 5: KRALİYET İRİS DİYAFRAM KASASI (IRIS_APERTURE)
    // -------------------------------------------------------------
    if (this.spec.mechanic === "IRIS_APERTURE") {
      const openRatio = this.openDuration / this.cycleLength;
      const closedHold = 0.40;
      const openEnd = closedHold + openRatio;

      if (progress < closedHold) {
        this.irisRadius += (0 - this.irisRadius) * Math.min(1, dt * 22);
        this.isOpen = false;
        this.isWarning = false;
        this.isSnapping = false;
        this.snapSoundPlayed = false;
      } else if (progress < openEnd - 0.12) {
        this.irisRadius += (this.irisMaxR - this.irisRadius) * Math.min(1, dt * 18);
        this.isOpen = this.irisRadius > 22;
        this.isWarning = false;
        this.isSnapping = false;
      } else if (progress < openEnd) {
        this.isOpen = true;
        this.isWarning = true;
        this.isSnapping = false;
      } else {
        this.irisRadius += (0 - this.irisRadius) * Math.min(1, dt * 26);
        this.isOpen = false;
        this.isWarning = false;
        this.isSnapping = true;
        if (!this.snapSoundPlayed && audio && isCurrentFloor) {
          audio.playMagnetSnap();
          if (particles) particles.spawnSparks(this.centerX, this.y);
          this.snapSoundPlayed = true;
        }
      }
      return;
    }

    // -------------------------------------------------------------
    // MEKANİZMA 1 & 4: STANDART SARKAÇ & RÜZGARLI KAPI (AKICI 6 FAZ)
    // -------------------------------------------------------------
    const openRatio = this.openDuration / this.cycleLength;
    const closedTime = this.cycleLength - this.openDuration;

    const closedHoldEnd = (closedTime * 0.68) / this.cycleLength;
    const swingUpEnd = closedHoldEnd + 0.15;
    const goldenEnd = swingUpEnd + (this.openDuration - 0.22) / this.cycleLength;
    const warningEnd = swingUpEnd + this.openDuration / this.cycleLength;
    const slamEnd = warningEnd + 0.08;

    if (progress < closedHoldEnd) {
      this.targetFlapAngle = 0;
      this.isOpen = false;
      this.isWarning = false;
      this.isSnapping = false;
      this.snapSoundPlayed = false;
    } else if (progress < swingUpEnd) {
      const t = (progress - closedHoldEnd) / 0.15;
      this.targetFlapAngle = Math.sin((t * Math.PI) / 2) * 1.55;
      this.isOpen = t > 0.40;
      this.isWarning = false;
      this.isSnapping = false;
      this.snapSoundPlayed = false;
    } else if (progress < goldenEnd) {
      const t = (progress - swingUpEnd) / ((goldenEnd - swingUpEnd) || 0.01);
      this.targetFlapAngle = 1.55 + Math.sin(t * Math.PI * 2) * 0.04;
      this.isOpen = true;
      this.isWarning = false;
      this.isSnapping = false;
    } else if (progress < warningEnd) {
      const t = (progress - goldenEnd) / ((warningEnd - goldenEnd) || 0.01);
      this.targetFlapAngle = 1.52 - t * 0.18 + Math.sin(t * Math.PI * 8) * 0.03;
      this.isOpen = true;
      this.isWarning = true;
      this.isSnapping = false;
    } else if (progress < slamEnd) {
      const t = (progress - warningEnd) / 0.08;
      this.targetFlapAngle = Math.max(0, (1.0 - t * t) * 1.34);
      this.isOpen = t < 0.15;
      this.isWarning = false;
      this.isSnapping = true;
    } else {
      this.isOpen = false;
      this.isWarning = false;
      this.isSnapping = false;

      if (!this.snapSoundPlayed && audio && isCurrentFloor) {
        audio.playMagnetSnap();
        if (particles) particles.spawnSparks(this.centerX, this.y);
        this.snapSoundPlayed = true;
      }
      const t = (progress - slamEnd) / ((1.0 - slamEnd) || 0.01);
      this.targetFlapAngle = Math.max(0, Math.sin(t * Math.PI * 3) * 0.06 * Math.exp(-t * 6));
    }

    this.flapAngle += (this.targetFlapAngle - this.flapAngle) * Math.min(1, dt * 22);

    if (this.impactRattle > 0) {
      this.impactRattle = Math.max(0, this.impactRattle - dt * 2.5);
    }
  }

  checkCollision(cat, dt, audio = null, particles = null) {
    this.glowLeft = Math.max(0, this.glowLeft - dt * 4);
    this.glowRight = Math.max(0, this.glowRight - dt * 4);
    const top = this.y - this.height / 2;
    const bot = this.y + this.height / 2;
    const c = cat.getCenter();

    // 4. Aşama Sekme Pedi Çarpışması (Trickshot Bouncer Sofa)
    // KRİTİK: Her atışta sadece 1 kez tetiklenir (!hasBouncedThisLaunch), yay salınımıyla çoklu tetikleme önlenir
    if (this.spec.mechanic === "WIND_BOUNCE" && !this.hasBouncedThisLaunch) {
      const bTop = this.y + (this.bouncerYOffset !== undefined ? this.bouncerYOffset : 90);
      const bBot = bTop + (this.bouncerH || 180);
      let hitTriggered = false;

      // Kedi bouncera değdi mi?
      for (let i = 0; i < cat.pointList.length; i++) {
        const pt = cat.pointList[i];
        if (pt.x > this.bouncerX - 26 && pt.y > bTop - 20 && pt.y < bBot + 20 && pt.vx > 0) {
          hitTriggered = true;
          break;
        }
      }

      if (hitTriggered) {
        this.bouncerHitTimer = 0.45; // Derin sünger esnemesi
        this.hasBouncedThisLaunch = true; // Bouncer şartı sağlandı!
        if (audio && audio.playBoing) audio.playBoing();
        if (particles) particles.spawnSparks(this.bouncerX - 20, c.y);

        // BÜTÜNSEL KÜTLE İTKİSİ (Whole-Body Impulse):
        // Kedinin tüm soft-body noktaları eşzamanlı olarak kapıya yönlenir (yay sönümlenmesi sıfırlanır)
        cat.pointList.forEach(pt => {
          pt.x = Math.min(pt.x, this.bouncerX - 25);
          pt.vx = -460; // Trambolinden sola kapı açıklığına (X=225) güçlü açılı falso kavis
          pt.vy = -760; // Tavan engeline toslamadan kapı eşiğinden içeri dalış açısı
        });
      }

      // 4. Kat Fırtına Sundurması (Balcony Canopy): Doğrudan dikey geçişi engelleyen fiziksel kalkan
      // SADECE VE SADECE bouncera çarpmadan önceki doğrudan atışları engeller (trickshot kavisini kesmez!)
      if (!this.hasBouncedThisLaunch) {
        const canopyY = this.y + (this.canopyYOffset !== undefined ? this.canopyYOffset : 190);
        const canopyW = this.canopyW || 295;
        const canopyH = this.canopyH || 22;
        cat.pointList.forEach(pt => {
          if (pt.x < canopyW && pt.y > canopyY && pt.y < canopyY + canopyH + 20 && pt.vy < 0) {
            pt.y = canopyY + canopyH + 20;
            pt.vy = Math.abs(pt.vy) * 0.45 + 140; // Tok metalik çarpıp düşme
            if (audio && audio.playMetallicBonk) audio.playMetallicBonk();
            if (particles) particles.spawnSparks(pt.x, canopyY + canopyH);
          }
        });
      }
    }

    // 2. Aşama: 3 Bölmeli Lüks Otel Döner Camı & Süpüren Engel Çarpışması (ROTATING_FAN)
    // Konsorsiyum Mimarisi: Mert & Burak (Ritmik Zamanlama, Adil Açık Koridor & Polar Fizik)
    if (this.spec.mechanic === "ROTATING_FAN" && cat.isLaunched) {
      const fanR = this.spec.fanRadius || 64;
      const cx = this.centerX;
      const cy = this.y;

      // Kedi dikey olarak çarkın etki alanındayken (cy - fanR ile cy + fanR + 24)
      if (c.y < cy + fanR + 24 && c.y > cy - fanR - 16) {
        // Alt giriş ekseni: Math.PI / 2 (Aşağıdan yukarıya dikey geçiş)
        let minEntryDiff = Math.PI;
        for (let b = 0; b < 3; b++) {
          const bAngle = (this.fanAngle + (b * Math.PI * 2) / 3) % (Math.PI * 2);
          const diff = Math.abs((((bAngle - Math.PI / 2) + Math.PI) % (Math.PI * 2)) - Math.PI);
          if (diff < minEntryDiff) minEntryDiff = diff;
        }

        // Kanat dikey geçiş koridorunu kapatıyorsa (engel anı - kırmızı kapalı hız ve tolerans artışı):
        const bladeHazardSpan = (this.spec.bladeHazardSpan || 0.45); // ~26° süpüren kanat engeli (0.33 -> 0.45 rad)
        if (minEntryDiff < bladeHazardSpan) {
          // Kanat alt giriş veya dikey koridorda kediye çarpar!
          this.hasCollidedBlade = true;
          this.applyImpactShudder(1.8);
          cat.isGlassSmushed = true;
          cat.glassSmushTimer = 0.95;

          if (audio && audio.playGlassSmush) audio.playGlassSmush();

          if (minEntryDiff > bladeHazardSpan - 0.08) {
            return "NEAR_MISS_BLADE";
          }
          return "BONK_BLADE";
        } else if (minEntryDiff < bladeHazardSpan + 0.14) {
          this.wasCloseCall = true;
        }

        // Dairesel Dış Çerçeve Çarpışması: Kedi yatayda çarkın dışına fırlarsa
        for (let i = 0; i < cat.pointList.length; i++) {
          const pt = cat.pointList[i];
          if (Math.abs(pt.y - cy) < 26) {
            const distFromCenter = Math.hypot(pt.x - cx, pt.y - cy);
            if (distFromCenter > fanR + 2 && distFromCenter < fanR + 28) {
              this.applyImpactShudder(1.2);
              if (audio && audio.playMetallicBonk) audio.playMetallicBonk();
              return "BONK_BLADE";
            }
          }
        }
      }
    }

    // 3. Aşama: Siber X-Ray Tarayıcısı (Kedi lazer alanındayken iskeleti parlar)
    if (this.spec.mechanic === "SLIDING_GUILLOTINE" && cat.isLaunched) {
      if (Math.abs(c.x - this.centerX) < this.width / 2 + 18 && Math.abs(c.y - this.y) < 58) {
        cat.isXRayActive = true;
        cat.xRayTimer = 0.40;
        if (!this.isOpen && Math.abs(c.y - this.y) < 38) {
          const edgeDist = Math.abs(Math.abs(c.x - this.centerX) - this.width / 2);
          if (edgeDist < 14 || (this.isWarning && edgeDist < 20)) {
            return "NEAR_MISS_GUILLOTINE";
          }
          return "BONK_BLADE";
        }
      }
    }

    // 5. Aşama: İris Diyafram Kapanma Çarpışması (IRIS_APERTURE)
    // Sorumlu: Mert & Burak — Doğru Dikey Portal Geçiş Geometrisi
    if (this.spec.mechanic === "IRIS_APERTURE" && cat.isLaunched) {
      if (Math.abs(c.y - this.y) < 22) {
        const lateralDist = Math.abs(c.x - this.centerX);
        // Sıkışmış kedi yarıçapı (~12px) ile iris açıklığı kontrolü
        if (lateralDist + 12 > this.irisRadius) {
          if (this.irisRadius > 18) {
            return "NEAR_MISS_IRIS";
          } else {
            return "BONK_IRIS";
          }
        } else if (lateralDist + 16 > this.irisRadius) {
          this.wasCloseCall = true;
        }
      }
    }

    // Pervaz ve Yan Duvar Çarpışmaları (Giyotin, Standart ve Rüzgarlı Kapılar)
    cat.pointList.forEach(pt => {
      // Sol pervaz yönlendirici huni (Kat 4 trickshot için genişletilmiş kavis)
      const leftFunnelSpan = (this.spec.mechanic === "WIND_BOUNCE") ? 45 : 26;
      if (pt.x > this.leftPostX - leftFunnelSpan && pt.x < this.leftPostX + 18) {
        const archTop = (this.spec.mechanic === "WIND_BOUNCE") ? (top - 12) : top;
        const archBot = (this.spec.mechanic === "WIND_BOUNCE") ? (bot + 30) : bot;
        if (pt.y + pt.radius > archTop && pt.y - pt.radius < archBot) {
          const pushIn = (this.leftPostX + 18 - pt.x);
          if (pushIn > 0) {
            pt.x += pushIn * 0.20;
            pt.vx += pushIn * 18 * dt * 60;
            pt.vy *= 0.96;
            this.glowLeft = 1;
          }
        }
      }
      // Sağ pervaz yönlendirici huni (Kat 4 açılı trickshot için kavisli kemer mimarisi)
      const rightFunnelSpan = (this.spec.mechanic === "WIND_BOUNCE") ? 55 : 26;
      if (pt.x > this.rightPostX - 18 && pt.x < this.rightPostX + rightFunnelSpan) {
        const archTop = (this.spec.mechanic === "WIND_BOUNCE") ? (top - 12) : top;
        const archBot = (this.spec.mechanic === "WIND_BOUNCE") ? (bot + 30) : bot;
        if (pt.y + pt.radius > archTop && pt.y - pt.radius < archBot) {
          const pushIn = (pt.x - (this.rightPostX - 18));
          if (pushIn > 0) {
            pt.x -= pushIn * 0.20;
            pt.vx -= pushIn * 18 * dt * 60;
            pt.vy *= 0.96;
            this.glowRight = 1;
          }
        }
      }
      // Katı yan duvar engeli
      const leftWallBound = (this.spec.mechanic === "WIND_BOUNCE") ? (this.leftPostX - leftFunnelSpan) : (this.leftPostX - 14);
      const rightWallBound = (this.spec.mechanic === "WIND_BOUNCE") ? (this.rightPostX + rightFunnelSpan) : (this.rightPostX + 14);
      if (pt.x < leftWallBound || pt.x > rightWallBound) {
        if (pt.y + pt.radius > top && pt.y - pt.radius < bot) {
          if (pt.y > this.y) {
            pt.y = bot + pt.radius;
            pt.vy = Math.abs(pt.vy) * 0.4;
          } else {
            pt.y = top - pt.radius;
            pt.vy = -Math.abs(pt.vy) * 0.4;
          }
        }
      }
    });

    return null;
  }

  // =============================================================
  // PLATFORM ÇİZİMİ (KİLİTLİ ZEMİN MİMARİSİ — ASLA AŞAĞI DÜŞÜRMEYEN SİSTEM)
  // =============================================================
  drawPlatform(ctx, currentFloor) {
    ctx.save();
    const py = this.platformY;
    const isCurrent = (this.floorNumber === currentFloor);
    const isPassed = (this.floorNumber < currentFloor);

    // KURAL: Eğer kedi bu kattaysa VEYA bu kat önceden geçilmişse,
    // zemin %100 YEKPARE VE MÜHÜRLÜ ÇELİK KİRİŞTİR (Delik veya kuyu yoktur!)
    if (this.floorNumber === 1 || isCurrent || isPassed) {
      const beamH = (this.floorNumber === 1) ? 120 : 26;
      ctx.fillStyle = this.spec.platformColor || "#1b1130";
      ctx.fillRect(0, py, this.config.CANVAS_WIDTH, beamH);

      // Üst Neon Çizgisi
      ctx.strokeStyle = this.spec.themeColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = this.spec.themeColor;
      ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.moveTo(0, py);
      ctx.lineTo(this.config.CANVAS_WIDTH, py);
      ctx.stroke();

      // Mühürlü Çelik Izgara & Emniyet Işıkları
      if (this.floorNumber > 1) {
        ctx.fillStyle = "rgba(0, 0, 0, 0.4)";
        ctx.fillRect(18, py + 4, this.config.CANVAS_WIDTH - 36, beamH - 8);

        // Kilitli Çelik Izgara Çizgileri
        ctx.strokeStyle = "rgba(255, 255, 255, 0.12)";
        ctx.lineWidth = 2;
        for (let gx = 30; gx < this.config.CANVAS_WIDTH - 30; gx += 20) {
          ctx.beginPath(); ctx.moveTo(gx, py + 4); ctx.lineTo(gx, py + beamH - 4); ctx.stroke();
        }

        // Yeşil Emniyet LED'leri (Zemin Kilitli & Güvenli)
        ctx.fillStyle = "#00ff88";
        ctx.shadowColor = "#00ff88";
        ctx.shadowBlur = 6;
        ctx.fillRect(24, py + 2, 4, 3);
        ctx.fillRect(this.config.CANVAS_WIDTH - 28, py + 2, 4, 3);
      }

      // Sadece aktif aşamada kalkış halkası çizilir
      if (isCurrent) {
        this.drawLaunchPadRing(ctx, this.centerX, py - 4, this.spec.themeColor);
      }
    } else {
      // ÜST KATLAR (Henüz ulaşılmamış katlar): Kedinin yukarı uçabilmesi için açık şaft
      // KRİTİK DÜZELTME (MERT & BURAK): Üst kat tavan şaftı sabit ve merkezlenmiş dikey asansör bacasıdır.
      // Henüz o kata ulaşılmamışken üst katın kayar kapıları (örn. 3. Kat giyotini) tavan kirişini hareket ettiremez!
      const beamH = 22;
      const shaftWidth = (this.spec.mechanic === "ROTATING_FAN") ? 128 : 100;
      const shaftCenterX = this.config.CANVAS_WIDTH / 2;
      const gapLeft = shaftCenterX - shaftWidth / 2 - 14;
      const gapRight = shaftCenterX + shaftWidth / 2 + 14;

      ctx.fillStyle = this.spec.platformColor || "#221538";
      ctx.fillRect(0, py, gapLeft, beamH);
      ctx.fillRect(gapRight, py, this.config.CANVAS_WIDTH - gapRight, beamH);

      ctx.strokeStyle = this.spec.themeColor;
      ctx.lineWidth = 2.5;
      ctx.shadowColor = this.spec.themeColor;
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.moveTo(0, py); ctx.lineTo(gapLeft, py);
      ctx.moveTo(gapRight, py); ctx.lineTo(this.config.CANVAS_WIDTH, py);
      ctx.stroke();
    }

    ctx.restore();
  }

  drawLaunchPadRing(ctx, cx, cy, color) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.shadowColor = color;
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.ellipse(cx, cy, 48, 12, 0, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = "rgba(255, 255, 255, 0.08)";
    ctx.fill();

    // İleri Fırlatma Oku
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 14);
    ctx.lineTo(cx - 8, cy - 6);
    ctx.lineTo(cx + 8, cy - 6);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
  }

  // =============================================================
  // 5 BENZERSİZ KAPI ÇİZİMİ
  // =============================================================
  draw(ctx, particles = null, isCurrentFloor = true, currentFloor = 1) {
    ctx.save();

    // 1. Kat Hedef Ödülü
    // SADECE mühürlenmemiş ve henüz geçilmemiş (mevcut veya sonraki) katlarda gösterilir!
    // Bir kat geçildiğinde, o katın ödülü KESİNLİKLE çizilmez (kedinin arkasında iz kalmaz).
    if (!this.isSealed && this.floorNumber >= currentFloor) {
      const treatY = (this.floorNumber === 5) ? (this.y - 95) : (this.y - 65);
      const treatX = this.centerX;
      this.drawFloorTreat(ctx, treatX, treatY, this.floorNumber, particles);
    }

    // 2. Kat Duvarı & Tematik Hat
    ctx.fillStyle = this.spec.wallColor || "#1e1438";
    ctx.fillRect(0, this.y - this.height / 2, this.leftPostX, this.height);
    ctx.fillRect(this.rightPostX, this.y - this.height / 2, this.config.CANVAS_WIDTH - this.rightPostX, this.height);

    ctx.strokeStyle = this.spec.themeColor || "#8800ff";
    ctx.shadowColor = this.spec.themeColor || "#8800ff";
    ctx.shadowBlur = 10;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(0, this.y + this.height / 2);
    ctx.lineTo(this.leftPostX, this.y + this.height / 2);
    ctx.moveTo(this.rightPostX, this.y + this.height / 2);
    ctx.lineTo(this.config.CANVAS_WIDTH, this.y + this.height / 2);
    ctx.stroke();

    // 3. Aşama Rozeti & İpucu (Sol Duvar)
    ctx.font = "900 13px -apple-system, monospace";
    ctx.fillStyle = this.spec.themeColor;
    ctx.shadowColor = this.spec.themeColor;
    ctx.shadowBlur = 8;
    ctx.textAlign = "left";
    ctx.fillText(`STAGE 0${this.floorNumber}`, 24, this.y - 18);
    ctx.font = "800 9px sans-serif";
    ctx.fillStyle = "rgba(255, 255, 255, 0.65)";
    ctx.shadowBlur = 0;
    ctx.fillText(this.spec.subtitle || this.spec.name, 24, this.y - 5);

    // Sağ Duvarda Oyuncu Başarı İstatistiği
    ctx.font = "800 9px monospace";
    ctx.fillStyle = "rgba(255, 255, 255, 0.45)";
    ctx.textAlign = "right";
    ctx.fillText(this.spec.percentile || "", this.config.CANVAS_WIDTH - 24, this.y - 10);

    // -----------------------------------------------------------
    // MEKANİZMAYA GÖRE ÖZEL ÇİZİM
    // -----------------------------------------------------------
    if (this.spec.mechanic === "ROTATING_FAN") {
      this.drawRotatingFan(ctx);
    } else if (this.spec.mechanic === "SLIDING_GUILLOTINE") {
      this.drawSlidingGuillotine(ctx);
    } else if (this.spec.mechanic === "WIND_BOUNCE") {
      this.drawWindBouncer(ctx, isCurrentFloor);
    } else if (this.spec.mechanic === "IRIS_APERTURE") {
      this.drawIrisAperture(ctx);
    } else {
      this.drawStandardFlap(ctx);
    }

    // Yan Pervazlar (Sadece Dikdörtgen Kapak ve Giyotin İçin Çizilir — Fan ve İris İçin Çizilmez)
    if (this.spec.mechanic !== "ROTATING_FAN" && this.spec.mechanic !== "IRIS_APERTURE") {
      const drawPost = (x, isLeft, glow) => {
        ctx.fillStyle = "#ffffff";
        ctx.shadowColor = glow > 0 ? "#ffff00" : "#ffffff";
        ctx.shadowBlur = glow > 0 ? 20 : 8;
        ctx.fillRect(x, this.y - 26, 10, 52);

        let postColor = glow > 0 ? "#ffff00" : (this.isOpen ? (this.isWarning ? "#ffcc00" : "#00ff88") : "#ff0055");
        ctx.fillStyle = postColor;
        ctx.shadowColor = postColor;
        ctx.shadowBlur = 14;
        ctx.fillRect(isLeft ? x + 3 : x + 1, this.y - 20, 6, 40);
      };
      drawPost(this.leftPostX - 10, true, this.glowLeft);
      drawPost(this.rightPostX, false, this.glowRight);
    }

    ctx.restore();
  }

  // 1. MEKANİZMA: STANDART SARKAÇ KAPAK (KAT 1: KUTU SENDROMU & EV KEDİ KAPISI)
  drawStandardFlap(ctx) {
    this.drawRhythmBar(ctx, this.centerX, this.y - this.height / 2 - 12);

    // Üst Metal Menteşe & Mikro Titreşim (Hinge Rattle Affordance)
    const hingeVibration = (this.isWarning || !this.isOpen) ? Math.sin(Date.now() * 0.04) * 1.5 : 0;
    ctx.save();
    ctx.fillStyle = "#8b9bb4";
    ctx.strokeStyle = "#475569";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.rect(this.centerX - this.width / 2 + 6 + hingeVibration, this.y - this.height / 2 - 4, 14, 6);
    ctx.rect(this.centerX + this.width / 2 - 20 + hingeVibration, this.y - this.height / 2 - 4, 14, 6);
    ctx.fill(); ctx.stroke();
    ctx.restore();

    const effectiveAngle = this.flapAngle + Math.sin(Date.now() * 0.05) * this.impactRattle;
    ctx.save();
    ctx.translate(this.centerX, this.y - this.height / 2);

    // Açıkken arkadaki sıcacık oturma odasından dökülen altın ışık huzmesi (Living Room Glow)
    if (this.isOpen) {
      const roomGlow = ctx.createRadialGradient(0, 10, 5, 0, 40, 85);
      roomGlow.addColorStop(0, "rgba(255, 215, 100, 0.45)");
      roomGlow.addColorStop(0.7, "rgba(255, 180, 50, 0.15)");
      roomGlow.addColorStop(1, "transparent");
      ctx.fillStyle = roomGlow;
      ctx.beginPath();
      ctx.moveTo(-this.width / 2, 0);
      ctx.lineTo(this.width / 2, 0);
      ctx.lineTo(this.width / 2 + 35, 90);
      ctx.lineTo(-this.width / 2 - 35, 90);
      ctx.closePath();
      ctx.fill();
    }

    ctx.rotate(-effectiveAngle);

    // Sıcak ahşap/akrilik kedi kapısı kapağı
    const flapColor = this.isOpen ? (this.isWarning ? "#ffcc00" : "#00ff88") : "#ff0055";
    ctx.fillStyle = this.isOpen ? "rgba(10, 40, 25, 0.75)" : "rgba(45, 12, 25, 0.85)";
    ctx.strokeStyle = flapColor;
    ctx.lineWidth = 3.0;
    ctx.shadowColor = flapColor;
    ctx.shadowBlur = 14;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(-this.width / 2 + 4, 0, this.width - 8, this.height + 15, 8) : ctx.rect(-this.width / 2 + 4, 0, this.width - 8, this.height + 15);
    ctx.fill(); ctx.stroke();

    // Sevimli Kedi Patisi Amblemi (Paw Print on Flap)
    ctx.fillStyle = flapColor;
    ctx.shadowBlur = 8;
    const pawY = (this.height + 15) / 2 - 4;
    ctx.beginPath();
    ctx.arc(0, pawY, 6, 0, Math.PI * 2);
    ctx.fill();
    [-7, -3, 3, 7].forEach((px, i) => {
      const py = pawY - 9 - (i === 1 || i === 2 ? 2 : 0);
      ctx.beginPath();
      ctx.arc(px, py, 2.8, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.font = "900 10.5px sans-serif";
    ctx.fillStyle = flapColor;
    ctx.textAlign = "center";
    ctx.fillText(this.isOpen ? "▲ ENTER ▲" : "🔒 LOCKED", 0, this.height + 11);
    ctx.restore();
  }

  // 2. MEKANİZMA: LÜKS OTEL DÖNER CAMI (KAT 2: REVOLVING GLASS DOOR & SWEEPING HAZARD)
  // Selin (Görsel Netlik & Sıfır Metin) ve Mert (Geometrik İllüstrasyon)
  drawRotatingFan(ctx) {
    const gateColor = this.isOpen ? (this.isWarning ? "#ffb700" : "#00ff88") : "#ff0055";

    // 1. Üst Ritim LED Barı (Oyuncunun ritmi okuyabilmesi için)
    this.drawRhythmBar(ctx, this.centerX, this.y - 74);

    ctx.save();
    ctx.translate(this.centerX, this.y);

    // 2. Ağır Çelik Portal Kasası (Dairesel Dış Çerçeve — Alt Giriş Portu Açık)
    const fanR = this.spec.fanRadius || 64;
    ctx.strokeStyle = "#334155";
    ctx.lineWidth = 7;
    ctx.beginPath();
    // Alt giriş kapısı (Math.PI * 0.35 - Math.PI * 0.65) açık bırakılır
    ctx.arc(0, 0, fanR, Math.PI * 0.68, Math.PI * 2.32);
    ctx.stroke();

    // Dairesel Neon Durum Halkası
    ctx.strokeStyle = gateColor;
    ctx.lineWidth = 3.5;
    ctx.shadowColor = gateColor;
    ctx.shadowBlur = 14;
    ctx.beginPath();
    ctx.arc(0, 0, fanR - 3, Math.PI * 0.68, Math.PI * 2.32);
    ctx.stroke();

    ctx.fillStyle = "rgba(10, 14, 24, 0.88)";
    ctx.fill();

    // 3. Alt Giriş Eşiği (Kapalıyken Kırmızı Lazer Bariyer, Açıkken Açık Giriş Portu)
    ctx.save();
    if (!this.isOpen || this.isWarning) {
      // Kapalı / Uyarı: Alt girişe lazer bariyer çekilir
      ctx.strokeStyle = gateColor;
      ctx.lineWidth = 5;
      ctx.shadowColor = gateColor;
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(0, 0, fanR - 3, Math.PI * 0.36, Math.PI * 0.64);
      ctx.stroke();
    } else {
      // Açık: Giriş ağzı tamamen açıktır; yeşil neon kılavuz pilonları parlar
      ctx.fillStyle = "#00ff88";
      ctx.shadowColor = "#00ff88";
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(-26, fanR - 6, 3.5, 0, Math.PI * 2);
      ctx.arc(26, fanR - 6, 3.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    // 4. Dönen 3 Güçlendirilmiş Cam Kanat (Revolving Glass Wings with Titanium Frame & Hazard Edge)
    ctx.save();
    ctx.rotate(this.fanAngle);

    for (let b = 0; b < 3; b++) {
      // Kanat Arka Planı (Şeffaf Kristal Emniyet Camı)
      ctx.fillStyle = this.isOpen ? "rgba(0, 255, 136, 0.16)" : "rgba(255, 0, 85, 0.22)";
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, 52, -0.22, 0.22);
      ctx.closePath();
      ctx.fill();

      // Cam Işık Yansıması Çizgileri
      ctx.strokeStyle = "rgba(255, 255, 255, 0.55)";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(14, -6);
      ctx.lineTo(42, 10);
      ctx.stroke();

      // Kanat Titanyum Taşıyıcı Omurga Çubuğu (Spine Segment)
      ctx.strokeStyle = "#cbd5e1";
      ctx.lineWidth = 3.5;
      ctx.shadowColor = gateColor;
      ctx.shadowBlur = 6;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(52, 0);
      ctx.stroke();

      // Dış Kanat Ucu Süpüren Tehlike Tamponu (Hazard Sweeper Bumper at Tip)
      ctx.fillStyle = gateColor;
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(50, 0, 6, 0, Math.PI * 2);
      ctx.fill();

      // Sarı/Siyah Uyarı İkaz Halkası
      ctx.strokeStyle = "#ffd166";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(50, 0, 3.5, 0, Math.PI * 2);
      ctx.stroke();

      ctx.rotate((Math.PI * 2) / 3);
    }
    ctx.restore();

    // 5. Merkez Rulman Hub Başlığı
    ctx.fillStyle = "#1e293b";
    ctx.strokeStyle = gateColor;
    ctx.lineWidth = 2.5;
    ctx.shadowColor = gateColor;
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill(); ctx.stroke();

    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.arc(0, 0, 4, 0, Math.PI * 2);
    ctx.fill();

    // 6. Cam Darbe Çatlağı (Eğer bonk olduysa örümcek ağı çatlak efekti)
    if (this.impactRattle > 0) {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.85)";
      ctx.lineWidth = 1.5;
      ctx.shadowColor = "#ffffff";
      ctx.shadowBlur = 8;
      for (let cr = 0; cr < 5; cr++) {
        const cAngle = cr * 1.25;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(Math.cos(cAngle) * 36, Math.sin(cAngle) * 36);
        ctx.stroke();
      }
    }

    // 7. Durum Metni (Zero-Text destekli net görsel durum)
    ctx.font = "900 11px -apple-system, monospace";
    ctx.fillStyle = gateColor;
    ctx.shadowColor = gateColor;
    ctx.shadowBlur = 8;
    ctx.textAlign = "center";
    ctx.fillText(
      this.isOpen ? (this.isWarning ? "⚠ SWEEPING ⚠" : "▲ PASSAGE OPEN ▲") : "⛔ BLOCKED - ROTATING ⛔",
      0,
      78
    );

    ctx.restore();
  }

  // 3. MEKANİZMA: SİBER X-RAY GÜVENLİK TARAYICISI (KAT 3: CYBER LUGGAGE SCANNER)
  drawSlidingGuillotine(ctx) {
    const trackY = this.y - this.height / 2 - 14;
    // 🩻 Siber X-Ray Bagaj Tarayıcı Ray Hattı
    ctx.strokeStyle = "rgba(0, 255, 255, 0.35)";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(this.config.CANVAS_WIDTH / 2 - 95, trackY);
    ctx.lineTo(this.config.CANVAS_WIDTH / 2 + 95, trackY);
    ctx.stroke();

    // Ray Rulman Kılavuz Dişleri
    ctx.strokeStyle = "rgba(0, 255, 255, 0.6)";
    ctx.lineWidth = 1.5;
    for (let rx = this.config.CANVAS_WIDTH / 2 - 90; rx <= this.config.CANVAS_WIDTH / 2 + 90; rx += 15) {
      ctx.beginPath();
      ctx.moveTo(rx, trackY - 3); ctx.lineTo(rx, trackY + 3);
      ctx.stroke();
    }

    // 2. Kayan Hidrolik Lazer Çerçevesi
    const gateColor = this.isOpen ? (this.isWarning ? "#ffcc00" : "#00ff88") : "#ff0055";
    ctx.save();
    ctx.translate(this.centerX, this.y);

    // Dikey Parlayan Cyan Lazer Röntgen Perdesi (X-Ray Scanner Curtain)
    ctx.strokeStyle = "rgba(0, 255, 255, 0.75)";
    ctx.shadowColor = "#00ffff";
    ctx.shadowBlur = 14;
    ctx.lineWidth = 2.0;
    ctx.setLineDash([6, 3]);
    ctx.beginPath();
    ctx.moveTo(0, -this.height / 2);
    ctx.lineTo(0, this.height + 250);
    ctx.stroke();
    ctx.setLineDash([]);

    // Açıklık Çerçevesi
    ctx.strokeStyle = gateColor;
    ctx.lineWidth = 3.5;
    ctx.shadowColor = gateColor;
    ctx.shadowBlur = 14;
    ctx.fillStyle = this.isOpen ? "rgba(0, 255, 255, 0.22)" : "rgba(255, 0, 85, 0.35)";
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(-this.width / 2 + 4, -this.height / 2, this.width - 8, this.height + 15, 6) : ctx.rect(-this.width / 2 + 4, -this.height / 2, this.width - 8, this.height + 15);
    ctx.fill(); ctx.stroke();

    // Sarı/Siyah Tehlike Çizgileri (Hazard Stripes)
    ctx.strokeStyle = "rgba(255, 209, 102, 0.55)";
    ctx.lineWidth = 2;
    for (let hx = -this.width / 2 + 10; hx < this.width / 2 - 10; hx += 16) {
      ctx.beginPath();
      ctx.moveTo(hx, -this.height / 2 + 2);
      ctx.lineTo(hx + 8, -this.height / 2 + 12);
      ctx.stroke();
    }

    // Durum Başlığı
    ctx.font = "900 11px sans-serif";
    ctx.fillStyle = gateColor;
    ctx.textAlign = "center";
    ctx.fillText(this.isOpen ? "🩻 X-RAY OPEN" : "⚡ SCANNER SCANNING", 0, this.height + 6);

    ctx.restore();
  }

  // 4. MEKANİZMA: FIRTINA MENFEZİ & KADİFE KOLTUK TRICKSHOT (KAT 4: VELVET SOFA BOUNCER)
  drawWindBouncer(ctx, isCurrentFloor) {
    this.drawStandardFlap(ctx);

    // 🌪️ Lüks Yaylı Kadife Kedi Koltuğu (Velvet Scratcher Sofa Bouncer)
    const isHit = this.bouncerHitTimer > 0;
    const compression = isHit ? Math.sin(this.bouncerHitTimer * Math.PI * 4) * 14 : 0;
    const bx = this.bouncerX - compression;
    const by = this.y + (this.bouncerYOffset !== undefined ? this.bouncerYOffset : 90);
    const bh = this.bouncerH || 180;

    ctx.save();

    // Koltuğun arkasındaki 3 Çelik Helezon Yay (Heavy Compression Springs)
    ctx.strokeStyle = "#ffd700";
    ctx.lineWidth = 2.5;
    [by + 28, by + bh / 2, by + bh - 28].forEach(sy => {
      ctx.beginPath();
      ctx.moveTo(bx, sy);
      ctx.lineTo(bx + 12, sy - 4);
      ctx.lineTo(bx + 16, sy + 4);
      ctx.lineTo(this.config.CANVAS_WIDTH, sy);
      ctx.stroke();
    });

    // Kadife Kapitoneli Koltuk Yastığı Gövdesi (Deep Tufted Velvet Cushion)
    const sofaGrad = ctx.createLinearGradient(bx - 24, by, bx, by);
    sofaGrad.addColorStop(0, isHit ? "#ff007f" : "#a8165b");
    sofaGrad.addColorStop(1, isHit ? "#ffffff" : "#ff2a6d");
    ctx.fillStyle = sofaGrad;
    ctx.strokeStyle = isHit ? "#ffffff" : "#ff007f";
    ctx.lineWidth = 3.5;
    ctx.shadowColor = isHit ? "#ffff00" : "#ff007f";
    ctx.shadowBlur = isHit ? 30 : 16;

    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(bx - 22, by, 22, bh, 10) : ctx.rect(bx - 22, by, 22, bh);
    ctx.fill(); ctx.stroke();

    // Kapitone Düğmeleri (Diamond Tufting Buttons)
    ctx.fillStyle = "#ffffff";
    ctx.shadowBlur = 6;
    for (let ty = by + 22; ty < by + bh - 10; ty += 26) {
      ctx.beginPath();
      ctx.arc(bx - 11, ty, 3, 0, Math.PI * 2);
      ctx.fill();
    }

    // 💥 Dairesel Nabız Halesi (Trickshot Visual Affordance Wave)
    if (!isHit && isCurrentFloor) {
      const pulseWave = (Date.now() * 0.005) % 1;
      ctx.strokeStyle = `rgba(0, 229, 255, ${1.0 - pulseWave})`;
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.arc(bx - 22, by + bh / 2, 16 + pulseWave * 28, -Math.PI / 2, Math.PI / 2, true);
      ctx.stroke();

      ctx.fillStyle = "rgba(255, 255, 255, 0.95)";
      ctx.font = "900 11px monospace";
      ctx.textAlign = "right";
      ctx.fillText("◀ AIM HERE!", bx - 26, by + bh / 2 + 4);
    }

    // 🛡️ 4. Kat Fırtına Sundurması (Balcony Storm Canopy & Glass Deflector)
    // SIFIR METİN KURALI: Doğrudan dikey geçiş yolunun kapalı olduğunu, tek yolun sağdaki menfez olduğunu anında gösterir!
    const canopyY = this.y + (this.canopyYOffset !== undefined ? this.canopyYOffset : 190);
    const canopyW = this.canopyW || 295;
    const canopyH = this.canopyH || 22;

    // 1. Ağır Çelik Taşıyıcı Konsol Kirişleri
    ctx.strokeStyle = "#162842";
    ctx.lineWidth = 3.5;
    [32, 105, 180, 255].forEach(gx => {
      ctx.beginPath();
      ctx.moveTo(gx, canopyY + canopyH);
      ctx.lineTo(gx - 18, canopyY + canopyH + 28);
      ctx.stroke();
    });

    // 2. Sundurma Gövdesi (Siyah Titanyum ve Neon Cam)
    const canopyGrad = ctx.createLinearGradient(0, canopyY, 0, canopyY + canopyH);
    canopyGrad.addColorStop(0, "#0c1524");
    canopyGrad.addColorStop(0.5, "#182c48");
    canopyGrad.addColorStop(1, "#0a111c");
    ctx.fillStyle = canopyGrad;
    ctx.strokeStyle = "#00e5ff";
    ctx.lineWidth = 2.5;
    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 14;

    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(0, canopyY, canopyW, canopyH, [0, 8, 8, 0]) : ctx.rect(0, canopyY, canopyW, canopyH);
    ctx.fill(); ctx.stroke();

    // 3. Tehlike Şeritleri (Cyan Hazard Warning Stripes)
    ctx.fillStyle = "rgba(0, 229, 255, 0.40)";
    for (let hx = 12; hx < canopyW - 14; hx += 24) {
      ctx.beginPath();
      ctx.moveTo(hx, canopyY + 3);
      ctx.lineTo(hx + 10, canopyY + 3);
      ctx.lineTo(hx + 4, canopyY + canopyH - 3);
      ctx.lineTo(hx - 6, canopyY + canopyH - 3);
      ctx.closePath();
      ctx.fill();
    }

    // 4. Mimari Titanyum Perçinler & Neon Emniyet Göstergesi (Sıfır Metin Kuralı)
    ctx.fillStyle = "#00e5ff";
    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 6;
    for (let rx = 18; rx < canopyW - 10; rx += 36) {
      ctx.beginPath();
      ctx.arc(rx, canopyY + canopyH / 2, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Dinamik Uçuşan Çoraplar & Kağıtlar (Flying Laundry Swirls in Gale Wind)
    if (isCurrentFloor) {
      const now = Date.now();
      const totalWidth = this.config.CANVAS_WIDTH + 140;

      // 8 Katmanlı Rüzgar Akımı
      for (let i = 0; i < 8; i++) {
        const streamSpeed = 220 + (i % 3) * 60;
        const wy = this.y + 20 + i * 46;
        const progress = ((now * (streamSpeed / 1000) + i * 73) % totalWidth);
        const wx = this.config.CANVAS_WIDTH + 80 - progress;
        const streamLen = 50 + (i % 4) * 25;
        const waveY = Math.sin(wx * 0.02 + now * 0.004) * 4;

        const grad = ctx.createLinearGradient(wx, wy + waveY, wx + streamLen, wy + waveY);
        grad.addColorStop(0, "rgba(0, 229, 255, 0.75)");
        grad.addColorStop(0.7, "rgba(0, 229, 255, 0.25)");
        grad.addColorStop(1, "rgba(0, 229, 255, 0)");

        ctx.strokeStyle = grad;
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.moveTo(wx, wy + waveY);
        ctx.lineTo(wx + streamLen, wy + waveY);
        ctx.stroke();
      }

      ctx.font = "800 10px monospace";
      ctx.fillStyle = "rgba(0, 229, 255, 0.75)";
      ctx.textAlign = "left";
      ctx.fillText("◀ GALE WIND (-520G)", 24, this.y + 45);
    }
    ctx.restore();
  }

  // 5. MEKANİZMA: KRALİYET KASASI: 3 HALKALI ŞİFRE ÇARKI & ALTIN SOMON (KAT 5: THE VAULT ECLIPSE)
  drawIrisAperture(ctx) {
    ctx.save();
    ctx.translate(this.centerX, this.y);

    // 👑 KRALİYET KASASI: 3 Eşmerkezli Dönen Şifre Çarkı & Altın Somon (The Vault Eclipse)
    const now = Date.now();

    // 1. Dış Dişli Çark (Outer Gear Ring)
    ctx.save();
    ctx.rotate(now * 0.0006);
    ctx.strokeStyle = "#ffd700";
    ctx.lineWidth = 3.5;
    ctx.shadowColor = "#ffd700";
    ctx.shadowBlur = 18;
    ctx.beginPath();
    ctx.arc(0, 0, 56, 0, Math.PI * 2);
    ctx.stroke();
    // Dişli tırnakları
    for (let g = 0; g < 12; g++) {
      const ga = (g * Math.PI * 2) / 12;
      ctx.strokeRect(Math.cos(ga) * 54 - 3, Math.sin(ga) * 54 - 3, 6, 6);
    }
    ctx.restore();

    // 2. Orta Şifre Halkası (Middle Roman Cipher Dial)
    ctx.save();
    ctx.rotate(-now * 0.0008);
    ctx.strokeStyle = "rgba(255, 215, 0, 0.55)";
    ctx.lineWidth = 2.0;
    ctx.beginPath();
    ctx.arc(0, 0, 47, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();

    // 3. ✨ AÇIKKEN DIŞARIYA FIŞKIRAN ALTIN IŞIK HÜZMELERİ (God Rays of the Royal Vault)
    if (this.isOpen) {
      ctx.save();
      ctx.rotate(now * 0.0012);
      for (let r = 0; r < 8; r++) {
        const ra = (r * Math.PI * 2) / 8;
        ctx.fillStyle = "rgba(255, 215, 0, 0.18)";
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(Math.cos(ra - 0.12) * 120, Math.sin(ra - 0.12) * 120);
        ctx.lineTo(Math.cos(ra + 0.12) * 120, Math.sin(ra + 0.12) * 120);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }

    // Diyafram Bıçakları (6 Ağır Altın Plaka)
    const r = this.irisRadius;
    ctx.fillStyle = "rgba(28, 18, 8, 0.95)";
    ctx.strokeStyle = "#ffd700";
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.arc(0, 0, 44, 0, Math.PI * 2);
    ctx.arc(0, 0, Math.max(0, r), 0, Math.PI * 2, true);
    ctx.fill(); ctx.stroke();

    // Açıklık İbaresi
    ctx.font = "900 10.5px sans-serif";
    ctx.fillStyle = this.isOpen ? "#ffd700" : "#ff0055";
    ctx.textAlign = "center";
    ctx.shadowColor = ctx.fillStyle;
    ctx.shadowBlur = 10;
    ctx.fillText(this.isOpen ? "👑 ECLIPSE OPEN" : "🔒 VAULT LOCKED", 0, 4);

    ctx.restore();
  }

  // LED Ritim Barı
  drawRhythmBar(ctx, cx, cy) {
    ctx.save();
    const barW = this.width + 12;
    const barH = 7;

    ctx.fillStyle = "rgba(10, 6, 20, 0.88)";
    ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(cx - barW / 2, cy - barH / 2, barW, barH, 4) : ctx.rect(cx - barW / 2, cy - barH / 2, barW, barH);
    ctx.fill(); ctx.stroke();

    const ledCount = 5;
    const step = (barW - 14) / (ledCount - 1);
    const startX = cx - barW / 2 + 7;

    for (let i = 0; i < ledCount; i++) {
      const lx = startX + i * step;
      let ledColor = this.isOpen ? (this.isWarning ? "#ffcc00" : "#00ff88") : "#ff0055";
      ctx.fillStyle = ledColor;
      ctx.shadowColor = ledColor;
      ctx.shadowBlur = 8;
      ctx.beginPath();
      ctx.arc(lx, cy, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // Kat Hedef Ödülleri — 5 AŞAMAYA ÖZEL BENZERSİZ KADEMELİ GÖRSELLER
  drawFloorTreat(ctx, x, y, floor, particles) {
    ctx.save();
    if (particles && Math.random() < 0.22) {
      particles.spawnBowlSteam(x, y - 8);
    }

    if (floor === 1) {
      // 🥛 1. AŞAMA: Porselen Taze Süt Çanağı & Çıtır Balık Krakeri
      ctx.fillStyle = "rgba(56, 189, 248, 0.15)";
      ctx.beginPath(); ctx.arc(x, y, 42, 0, Math.PI * 2); ctx.fill();

      // Porselen Kase
      ctx.fillStyle = "#e2e8f0";
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(x, y, 22, 0, Math.PI); ctx.closePath(); ctx.fill(); ctx.stroke();

      // Süt Yüzeyi
      ctx.fillStyle = "#ffffff";
      ctx.beginPath(); ctx.ellipse(x, y - 2, 19, 5, 0, 0, Math.PI * 2); ctx.fill();

      // Yanında Çıtır Balık Krakeri
      ctx.fillStyle = "#f59e0b";
      ctx.beginPath(); ctx.ellipse(x + 16, y - 10, 8, 4, 0.3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 22, y - 10); ctx.lineTo(x + 28, y - 14); ctx.lineTo(x + 28, y - 6); ctx.closePath(); ctx.fill();

      ctx.font = "900 11px sans-serif";
      ctx.fillStyle = "#38bdf8";
      ctx.textAlign = "center";
      ctx.fillText("🥛 FRESH MILK", x, y - 24);
    } else if (floor === 2) {
      // 🍗 2. AŞAMA: Çıtır Şef Tavuk Budu & Havalı Güneş Gözlüğü
      ctx.fillStyle = "rgba(245, 158, 11, 0.18)";
      ctx.beginPath(); ctx.arc(x, y, 46, 0, Math.PI * 2); ctx.fill();

      // Çıtır Kızarmış Tavuk But
      ctx.fillStyle = "#d97706";
      ctx.beginPath(); ctx.ellipse(x - 2, y, 18, 12, -0.2, 0, Math.PI * 2); ctx.fill();

      // Kemik Ucu
      ctx.fillStyle = "#f8fafc";
      ctx.beginPath(); ctx.arc(x + 16, y - 6, 4, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 19, y - 1, 3.5, 0, Math.PI * 2); ctx.fill();

      // Havalı Güneş Gözlüğü (Kazanılacak Aksesuar)
      ctx.fillStyle = "#0f172a";
      ctx.strokeStyle = "#ffd700";
      ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.roundRect ? ctx.roundRect(x - 18, y - 18, 12, 7, 2) : ctx.rect(x - 18, y - 18, 12, 7); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.roundRect ? ctx.roundRect(x - 3, y - 18, 12, 7, 2) : ctx.rect(x - 3, y - 18, 12, 7); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x - 6, y - 15); ctx.lineTo(x - 3, y - 15); ctx.stroke();

      ctx.font = "900 11px sans-serif";
      ctx.fillStyle = "#ffd700";
      ctx.textAlign = "center";
      ctx.fillText("🍗 CRISPY CHICKEN", x, y - 24);
    } else if (floor === 3) {
      // 🍣 3. AŞAMA: Somon Nigiri Suşi & Ninja Bandanası
      ctx.fillStyle = "rgba(239, 68, 68, 0.18)";
      ctx.beginPath(); ctx.arc(x, y, 48, 0, Math.PI * 2); ctx.fill();

      // Suşi Pirinci
      ctx.fillStyle = "#f8fafc";
      ctx.beginPath(); ctx.ellipse(x, y + 2, 20, 8, 0, 0, Math.PI * 2); ctx.fill();

      // Taze Somon Dilimi
      ctx.fillStyle = "#f97316";
      ctx.beginPath(); ctx.ellipse(x, y - 2, 22, 7, 0, 0, Math.PI * 2); ctx.fill();

      // Somon Yağ Çizgileri
      ctx.strokeStyle = "rgba(255, 255, 255, 0.6)";
      ctx.lineWidth = 1.2;
      for (let sx = -12; sx <= 12; sx += 8) {
        ctx.beginPath(); ctx.moveTo(x + sx, y - 7); ctx.lineTo(x + sx + 4, y + 3); ctx.stroke();
      }

      // Nori Yosun Bandı
      ctx.fillStyle = "#14532d";
      ctx.fillRect(x - 4, y - 8, 8, 16);

      // Kırmızı Ninja Bandanası Kuyruğu
      ctx.fillStyle = "#ef4444";
      ctx.beginPath(); ctx.moveTo(x + 18, y - 14); ctx.lineTo(x + 28, y - 18); ctx.lineTo(x + 25, y - 8); ctx.closePath(); ctx.fill();

      ctx.font = "900 11px sans-serif";
      ctx.fillStyle = "#ff0055";
      ctx.textAlign = "center";
      ctx.fillText("🍣 SALMON NIGIRI", x, y - 24);
    } else if (floor === 4) {
      // 🦞 4. AŞAMA: Zümrüt Maine Istakozu & Süper Kahraman Pelerini
      ctx.fillStyle = "rgba(0, 229, 255, 0.20)";
      ctx.beginPath(); ctx.arc(x, y, 52, 0, Math.PI * 2); ctx.fill();

      // Zümrüt/Kızıl Istakoz Gövdesi
      ctx.fillStyle = "#ea580c";
      ctx.beginPath(); ctx.ellipse(x, y, 16, 12, 0, 0, Math.PI * 2); ctx.fill();

      // Dev Kıskaçlar
      ctx.fillStyle = "#c2410c";
      ctx.beginPath(); ctx.arc(x - 16, y - 6, 8, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 16, y - 6, 8, 0, Math.PI * 2); ctx.fill();

      // Zümrüt Parlaması
      ctx.fillStyle = "#10b981";
      ctx.shadowColor = "#10b981";
      ctx.shadowBlur = 8;
      ctx.beginPath(); ctx.arc(x, y - 2, 4, 0, Math.PI * 2); ctx.fill();
      ctx.shadowBlur = 0;

      // Uçuşan Kahraman Pelerini
      ctx.fillStyle = "#a855f7";
      ctx.beginPath(); ctx.moveTo(x - 14, y - 14); ctx.lineTo(x - 26, y - 22); ctx.lineTo(x - 18, y - 6); ctx.closePath(); ctx.fill();

      ctx.font = "900 11px sans-serif";
      ctx.fillStyle = "#00e5ff";
      ctx.textAlign = "center";
      ctx.fillText("🦞 MAINE LOBSTER", x, y - 26);
    } else {
      // 👑 5. AŞAMA: KRALİYET ALTIN SOMON BALIĞI TAHTI & ELMAS TAÇ!
      ctx.fillStyle = "rgba(255, 215, 0, 0.28)";
      ctx.beginPath(); ctx.arc(x, y, 68, 0, Math.PI * 2); ctx.fill();

      // Altın Balık Gövdesi
      ctx.fillStyle = "#ffd700";
      ctx.shadowColor = "#ffd700";
      ctx.shadowBlur = 28;
      ctx.beginPath(); ctx.ellipse(x, y, 36, 18, 0, 0, Math.PI * 2); ctx.fill();

      // Kuyruk
      ctx.beginPath();
      ctx.moveTo(x + 32, y);
      ctx.lineTo(x + 54, y - 18);
      ctx.lineTo(x + 54, y + 18);
      ctx.closePath();
      ctx.fill();

      // Balık Gözü
      ctx.fillStyle = "#0a0a1a";
      ctx.beginPath(); ctx.arc(x - 22, y - 4, 3.5, 0, Math.PI * 2); ctx.fill();

      // 👑 Altın & Elmas Kedi Tacı
      ctx.fillStyle = "#ffd700";
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x - 14, y - 22);
      ctx.lineTo(x - 14, y - 34);
      ctx.lineTo(x - 6, y - 26);
      ctx.lineTo(x, y - 38);
      ctx.lineTo(x + 6, y - 26);
      ctx.lineTo(x + 14, y - 34);
      ctx.lineTo(x + 14, y - 22);
      ctx.closePath();
      ctx.fill(); ctx.stroke();

      ctx.font = "900 13px sans-serif";
      ctx.fillStyle = "#ffd700";
      ctx.shadowColor = "#ffd700";
      ctx.shadowBlur = 14;
      ctx.textAlign = "center";
      ctx.fillText("👑 ROYAL SALMON", x, y - 44);
    }
    ctx.restore();
  }
}

class TowerManager {
  constructor(config = CONFIG) {
    this.config = config;
    this.doors = [];
    this.currentFloor = 1;
    this.setupTower();
  }

  setupTower() {
    this.doors = [];
    const total = this.config.TOTAL_STORY_FLOORS;
    for (let f = 1; f <= total; f++) {
      const spec = this.config.FLOORS[f - 1];
      const doorY = this.config.DOOR_Y - (f - 1) * this.config.FLOOR_HEIGHT;
      this.doors.push(new FloorDoor(f, doorY, spec, this.config));
    }
  }

  getCurrentDoor() {
    return this.doors[this.currentFloor - 1] || this.doors[this.doors.length - 1];
  }

  sealFloor(floorNum) {
    if (this.doors[floorNum - 1]) {
      this.doors[floorNum - 1].sealFloor();
    }
  }

  reset() {
    this.currentFloor = 1;
    this.doors.forEach(door => {
      door.isSealed = false;
      door.cycleTimer = 0;
      door.isOpen = false;
      door.isWarning = false;
      door.isSnapping = false;
      door.flapAngle = 0;
      door.targetFlapAngle = 0;
      door.wasOpenOnCatEntry = false;
      door.irisRadius = 0;
      door.snapSoundPlayed = false;
      door.fanAngle = 0;
      door.impactRattle = 0;
      door.glowLeft = 0;
      door.glowRight = 0;
    });
  }

  update(dt, audio, particles) {
    this.doors.forEach(door => {
      const isCurrent = (door.floorNumber === this.currentFloor);
      door.update(dt, audio, particles, isCurrent);
    });
  }

  draw(ctx, particles, cameraY) {
    this.drawTowerGirders(ctx, cameraY);

    this.doors.forEach(door => {
      const screenY = door.y - cameraY;
      if (screenY > -420 && screenY < this.config.CANVAS_HEIGHT + 420) {
        const isCurrent = (door.floorNumber === this.currentFloor);
        // Platform çizimi (Mühürlü ve kilitli taban kontrolü)
        door.drawPlatform(ctx, this.currentFloor);
        // Kapı mekanizması çizimi (Aktif kat bilgisi ile alt katların ödülü gizlenir)
        door.draw(ctx, particles, isCurrent, this.currentFloor);
      }
    });
  }

  drawTowerGirders(ctx, cameraY) {
    ctx.save();
    const minY = cameraY - 100;
    const maxY = cameraY + this.config.CANVAS_HEIGHT + 100;

    // Minimalist Yan Raylar
    ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(14, minY); ctx.lineTo(14, maxY);
    ctx.moveTo(this.config.CANVAS_WIDTH - 14, minY); ctx.lineTo(this.config.CANVAS_WIDTH - 14, maxY);
    ctx.stroke();

    ctx.restore();
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { FloorDoor, TowerManager };
}


// --- FILE: src/input.js ---
/**
 * TİLTOPİA — "KEDİ KAPI: KULE TIRMANIŞI" v6.0
 * src/input.js — Taktil Sapan Girişi, Anında Sıfırlama (Zero-Lag Hot Restart) & Güç Halkası
 * Sorumlular: Emre (Dopamin & Gösterge), Mert (Sıfır Gecikme), Zeynep (Pofuduk Modu)
 */

class InputHandler {
  constructor(canvas, cat, audio, engine, config = CONFIG) {
    this.canvas = canvas;
    this.cat = cat;
    this.audio = audio;
    this.engine = engine;
    this.config = config;

    this.isDragging = false;
    this.dragStart = { x: 0, y: 0 };
    this.currentPos = { x: 0, y: 0 };
    this.dragHoldTimer = 0;
    this.lastDragNotch = 0;
    this.hasInteracted = (typeof localStorage !== 'undefined' && localStorage.getItem("catdoor_has_played") === "1");

    this.setupEvents();
  }

  getPos(e) {
    const r = this.canvas.getBoundingClientRect();
    const screenX = (e.clientX - r.left) * (this.config.CANVAS_WIDTH / r.width);
    const screenY = (e.clientY - r.top) * (this.config.CANVAS_HEIGHT / r.height);
    // Kamera ofsetini ekle (Dünya koordinatları!)
    return {
      x: screenX,
      y: screenY + this.engine.cameraY
    };
  }

  setupEvents() {
    this.canvas.addEventListener("pointerdown", e => {
      this.audio.init();

      // EĞER OYUNCU BAŞARISIZ OLMUŞSA: Dokunulduğu an MEVCUT KATTA anında tüneğe oturur ve hemen yeni atış başlar!
      if (this.engine.gameState === "FAIL" || this.cat.mode === "SPLAT") {
        this.cat.settleOnFloor(this.engine.currentFloor);
        this.engine.gameState = "IDLE";
        this.engine.timeScale = 1.0;
        this.engine.freezeFrameTimer = 0;
        this.engine.realSlowMoTimer = 0;
        this.audio.playInstantRestart();
      } else if (this.engine.gameState === "FLOOR_TRANSITION") {
        this.engine.fastPerchDrop();
        return;
      } else if (this.engine.gameState === "VICTORY_CLIMAX") {
        this.engine.finishVictoryClimax();
        return;
      } else if (this.engine.gameState === "SUCCESS") {
        this.engine.reset();
        this.audio.playInstantRestart();
        return;
      }

      if (this.cat.isLaunched) return;

      const pos = this.getPos(e);
      const c = this.cat.getCenter();
      const dist = Math.hypot(pos.x - c.x, pos.y - c.y);

      // Modern Ergonomik Sapan Başlatma:
      // Kediye yakın VEYA ekranın alt yarısında (pos.y > 330) herhangi bir yere dokunulunca başla!
      // Böylece oyuncu başparmağını ekranın ortasına koyup aşağı doğru ferah bir çekme alanına sahip olur.
      if (dist < 180 || pos.y > 330) {
        if (!this.hasInteracted) {
          this.hasInteracted = true;
          try { localStorage.setItem("catdoor_has_played", "1"); } catch (err) {}
        }
        this.isDragging = true;
        this.dragStart = { x: pos.x, y: pos.y };
        this.currentPos = { x: pos.x, y: pos.y };
        this.dragHoldTimer = 0;
        this.cat.mode = "DRAGGING";
        this.cat.dragIntensity = 0;
        this.cat.dragOffset = { x: 0, y: 0 };
        this.audio.playCatCuriousMew();
      }
    });

    window.addEventListener("pointermove", e => {
      if (this.isDragging) {
        this.currentPos = this.getPos(e);
        const dx = this.dragStart.x - this.currentPos.x;
        const dy = this.dragStart.y - this.currentPos.y;
        const dist = Math.hypot(dx, dy);

        // MAX_DRAG_DIST = 90px: Kısa ve ergonomik başparmak hareketi
        const intensity = Math.min(1.0, dist / this.config.MAX_DRAG_DIST);
        this.cat.dragIntensity = intensity;

        // Dokunsal Haptic Sapan Direnci (0.25, 0.50, 0.75, 1.0 eşiklerinde mekanik mikro tık)
        const currentNotch = Math.floor(intensity * 4);
        if (currentNotch > this.lastDragNotch) {
          if (this.engine.haptics) this.engine.haptics.pull();
          this.lastDragNotch = currentNotch;
        } else if (currentNotch < this.lastDragNotch) {
          this.lastDragNotch = currentNotch;
        }

        // Kedinin platform üzerindeki elastik çekilme mesafesi (en fazla 34px)
        const pullDirX = dist > 0 ? (this.currentPos.x - this.dragStart.x) / dist : 0;
        const pullDirY = dist > 0 ? (this.currentPos.y - this.dragStart.y) / dist : 0;
        this.cat.dragOffset = {
          x: pullDirX * intensity * 34,
          y: pullDirY * intensity * 34
        };

        this.audio.playSlingshotStretch(intensity);
      }
    });

    window.addEventListener("pointerup", () => {
      if (!this.isDragging) return;
      this.isDragging = false;
      this.lastDragNotch = 0;
      this.cat.dragIntensity = 0;
      this.cat.dragOffset = null;

      const dx = this.dragStart.x - this.currentPos.x;
      const dy = this.dragStart.y - this.currentPos.y;
      const dist = Math.hypot(dx, dy);

      if (dist > 16) {
        if (this.engine.haptics) this.engine.haptics.launch();
        const rawRatio = Math.min(dist, this.config.MAX_DRAG_DIST) / this.config.MAX_DRAG_DIST;
        // Taban güç desteği: En hafif atışta bile kedinin kapıya uçacak yeterli zıplama gücü olur
        const force = (0.38 + 0.62 * rawRatio) * this.config.MAX_LAUNCH_IMPULSE;

        let impulseX, impulseY;
        if (this.currentPos.y >= this.dragStart.y) {
          // Klasik Sapan (Geriye Çekip Bırakma): Aşağı çekilir, yukarı kapıya uçar
          impulseX = (dx / dist) * force;
          impulseY = -Math.abs((dy / dist) * force);
        } else {
          // Doğrudan Hedefe Kaydırma (Flick): Yukarı doğru kaydırılır, kapıya uçar
          impulseX = -(dx / dist) * force;
          impulseY = -Math.abs((dy / dist) * force);
        }

        if (this.engine.tower) {
          const curDoor = this.engine.tower.getCurrentDoor();
          if (curDoor) {
            curDoor.hasBouncedThisLaunch = false;
            curDoor.hasCollidedBlade = false;
            curDoor.wasOpenOnCatEntry = false;
          }
        }
        this.cat.isGlassSmushed = false;
        this.cat.glassSmushTimer = 0;
        this.cat.applyImpulse(impulseX, impulseY);
        this.audio.playLaunch();
        this.audio.playCatLaunchMeow();
      } else {
        this.cat.mode = "IDLE";
      }
    });

    window.addEventListener("keydown", e => {
      if (e.key === "r" || e.key === "R" || e.code === "Space") {
        this.engine.reset();
        this.audio.playInstantRestart();
      }
    });
  }

  update(dt) {
    // Sapan çekme esnasında temiz, odaklı ve öngörülebilir kontrol
  }

  // Sıfır Metin Onboarding Jesti (Zero-Text Onboarding Kinetic Hint)
  drawOnboardingHint(ctx) {
    if (this.hasInteracted || this.engine.currentFloor !== 1 || this.engine.gameState !== "IDLE" || this.isDragging) return;

    const c = this.cat.getCenter();
    const t = (Date.now() % 1600) / 1600; // 0..1
    const ease = Math.sin(t * Math.PI);
    const pullDist = ease * 52;
    const handX = c.x;
    const handY = c.y + 16 + pullDist;
    const alpha = Math.sin(t * Math.PI) * 0.85;

    ctx.save();

    // 1. Kedi Etrafında Yumuşak Nabız Halkası
    ctx.strokeStyle = `rgba(0, 245, 155, ${0.4 * (1 - ease)})`;
    ctx.shadowColor = "#00f59b";
    ctx.shadowBlur = 14;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(c.x, c.y + 4, 30 + ease * 16, 0, Math.PI * 2);
    ctx.stroke();

    // 2. Aşağı Doğru Çekme Yönünü Gösteren Kinetik Oklar (Chevrons)
    ctx.lineWidth = 3;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    for (let i = 0; i < 3; i++) {
      const cy = c.y + 24 + i * 14 + ease * 10;
      const chAlpha = Math.max(0, alpha - i * 0.22);
      ctx.strokeStyle = `rgba(0, 245, 155, ${chAlpha})`;
      ctx.shadowColor = "#00f59b";
      ctx.beginPath();
      ctx.moveTo(c.x - 12, cy - 6);
      ctx.lineTo(c.x, cy);
      ctx.lineTo(c.x + 12, cy - 6);
      ctx.stroke();
    }

    // 3. Çekilen Dokunuş Kapsülü (Glowing Touch Pill)
    ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
    ctx.shadowColor = "#00f59b";
    ctx.shadowBlur = 18;
    ctx.beginPath();
    ctx.arc(handX, handY, 13, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = `rgba(0, 245, 155, ${alpha * 0.9})`;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.arc(handX, handY, 19 + (1 - ease) * 8, 0, Math.PI * 2);
    ctx.stroke();

    ctx.restore();
  }

  drawSlingshot(ctx) {
    if (!this.isDragging) return;
    const c = this.cat.getCenter();
    const dx = this.dragStart.x - this.currentPos.x;
    const dy = this.dragStart.y - this.currentPos.y;
    const dist = Math.hypot(dx, dy);
    const power = Math.min(1.0, dist / this.config.MAX_DRAG_DIST);

    ctx.save();

    // 1. Gerilen Lastik Bantlar (Platform tüneğinden kedinin çekilen gövdesine)
    const stretchPoint = {
      x: c.x + (this.cat.dragOffset ? this.cat.dragOffset.x * 0.85 : 0),
      y: c.y + (this.cat.dragOffset ? this.cat.dragOffset.y * 0.85 : 0)
    };
    ctx.strokeStyle = power > 0.85 ? "#ff0055" : (power > 0.4 ? "#ffd700" : "#00ff88");
    ctx.lineWidth = 4.5;
    ctx.shadowColor = ctx.strokeStyle;
    ctx.shadowBlur = 14;
    ctx.beginPath();
    ctx.moveTo(c.x - 38, c.y);
    ctx.lineTo(stretchPoint.x, stretchPoint.y);
    ctx.moveTo(c.x + 38, c.y);
    ctx.lineTo(stretchPoint.x, stretchPoint.y);
    ctx.stroke();

    // 2. Oyuncunun Parmağı Altındaki Modern Güç Halkası
    ctx.lineWidth = 3.0;
    ctx.strokeStyle = power > 0.8 ? "#ff0055" : (power > 0.4 ? "#ffff00" : "#00ff88");
    ctx.shadowColor = ctx.strokeStyle;
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(this.currentPos.x, this.currentPos.y, 22 + power * 10, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * power);
    ctx.stroke();

    // Çekme Doğrultusu İnce Kılavuz Hattı
    ctx.strokeStyle = "rgba(255, 255, 255, 0.22)";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(this.dragStart.x, this.dragStart.y);
    ctx.lineTo(this.currentPos.x, this.currentPos.y);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.stroke();

    // 3. Gerçekçi Fizik Yörünge Yayı (Dinamik Hedef Önizlemesi)
    const currentDoor = this.engine.tower.getCurrentDoor();
    const curSpec = this.config.FLOORS[this.engine.currentFloor - 1];
    const windAcc = (curSpec && curSpec.mechanic === "WIND_BOUNCE") ? (curSpec.windForce || 0) : 0;

    const rawRatio = Math.min(dist, this.config.MAX_DRAG_DIST) / this.config.MAX_DRAG_DIST;
    const impulseForce = (0.38 + 0.62 * rawRatio) * this.config.MAX_LAUNCH_IMPULSE;
    let simVx, simVy;
    if (this.currentPos.y >= this.dragStart.y) {
      simVx = (dx / dist) * (impulseForce / 1.25);
      simVy = -Math.abs((dy / dist) * (impulseForce / 1.25));
    } else {
      simVx = -(dx / dist) * (impulseForce / 1.25);
      simVy = -Math.abs((dy / dist) * (impulseForce / 1.25));
    }

    let arcColor = (curSpec && curSpec.mechanic === "WIND_BOUNCE") ? "#00e5ff" : "#00ff88";
    const arcPoints = [];
    const steps = 14;
    const simDt = 0.040;
    let hasBounced = false;
    let curSimX = c.x;

    for (let i = 1; i <= steps; i++) {
      const t = simDt;
      if (curSpec && curSpec.mechanic === "WIND_BOUNCE") {
        simVx += windAcc * t;
      }
      simVy += this.config.GRAVITY * t;
      curSimX += simVx * t;
      const py = c.y + simVy * (i * simDt) * 0.5;

      // Sekme Pedi Yansıma Simülasyonu
      const bTop = curSpec.bouncerYOffset ? (currentDoor ? currentDoor.y + curSpec.bouncerYOffset : -1070) : (currentDoor ? currentDoor.y + 90 : -1070);
      const bBot = bTop + (curSpec.bouncerH || 180);
      if (curSpec && curSpec.mechanic === "WIND_BOUNCE" && !hasBounced && curSimX >= (curSpec.bouncerX - 26) && py >= bTop - 30 && py <= bBot + 30) {
        curSimX = curSpec.bouncerX - 25;
        simVx = -260;
        simVy = -820;
        hasBounced = true;
      }

      // Fırtına Sundurması Engeli Simülasyonu (Doğrudan dikey atış kırmızı ikaz)
      const canopyY = currentDoor ? (currentDoor.y + (curSpec.canopyYOffset || 190)) : -970;
      const canopyW = curSpec.canopyW || 295;
      if (curSpec && curSpec.mechanic === "WIND_BOUNCE" && !hasBounced && curSimX < canopyW && py < canopyY + 30) {
        arcColor = "#ff0055"; // Sundurmaya çarpacak
      }

      arcPoints.push({ x: curSimX, y: py, t: i * simDt });

      // Kapı hizasından geçerken çarpışma analizi
      if (currentDoor && Math.abs(py - currentDoor.y) < 28) {
        if (curSimX < currentDoor.leftPostX || curSimX > currentDoor.rightPostX) {
          arcColor = "#ff0055"; // Duvara çarpacak (Kırmızı Tehlike)
        } else if (curSimX < currentDoor.leftPostX + 12 || curSimX > currentDoor.rightPostX - 12) {
          arcColor = "#ffd700"; // Kenara yakın (Sarı Dikkat)
        }
      }
    }

    // Yörünge Noktalarını Çiz (Dinamik Nabız)
    ctx.fillStyle = arcColor;
    ctx.shadowColor = arcColor;
    ctx.shadowBlur = 10;
    arcPoints.forEach((pt, idx) => {
      const pR = Math.max(2, 4.5 - idx * 0.25 + Math.sin(Date.now() * 0.012 + idx) * 0.8);
      ctx.beginPath();
      ctx.arc(pt.x, pt.y, pR, 0, Math.PI * 2);
      ctx.fill();
    });

    // Yörünge Son Hedef Halkası
    if (arcPoints.length > 0) {
      const lastPt = arcPoints[arcPoints.length - 1];
      ctx.strokeStyle = arcColor;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(lastPt.x, lastPt.y, 8, 0, Math.PI * 2);
      ctx.stroke();
    }

    // 4. Slingshot Handle Indicator
    ctx.fillStyle = power > 0.85 ? "rgba(255, 0, 85, 0.75)" : "rgba(0, 255, 136, 0.65)";
    ctx.beginPath();
    ctx.arc(this.currentPos.x, this.currentPos.y, 14, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = InputHandler;
}


// --- FILE: src/game.js ---
/**
 * TİLTOPİA — "KEDİ KAPI: KULE TIRMANIŞI" v6.5
 * src/game.js — Kule Oyun Döngüsü, Dinamik Parallax Kamera, Kat Tırmanışı & Sıfır Gecikme
 * Konsorsiyum Mutabakatı: Baran, Mert, Defne, Selin, Burak, Kürşat, Ece, Emre, Kaan, Zeynep
 */

const FloorDoorClass = (typeof FloorDoor !== 'undefined') ? FloorDoor : (typeof require !== 'undefined' ? require('./door.js').FloorDoor : null);
const TowerManagerClass = (typeof TowerManager !== 'undefined') ? TowerManager : (typeof require !== 'undefined' ? require('./door.js').TowerManager : null);

class GameEngine {
  constructor() {
    this.canvas = document.getElementById("gameCanvas");
    this.ctx = this.canvas.getContext("2d");

    // UI Referansları
    this.scorePassesDisplay = document.getElementById("score-passes");
    this.scoreBestDisplay = document.getElementById("score-best");
    this.scoreNearmissDisplay = document.getElementById("score-nearmiss");
    this.floorDisplay = document.getElementById("floor-display");
    this.rageCounterDisplay = document.getElementById("rage-counter");
    this.ladderNodes = document.querySelectorAll(".ladder-node");

    // Modal & Kart Referansları
    this.retryContainer = document.getElementById("retry-container");
    this.retryTitle = document.getElementById("retry-title");
    this.retrySubtitle = document.getElementById("retry-subtitle");
    this.retryFloorBadge = document.getElementById("retry-floor-badge");
    this.retryPercentileBadge = document.getElementById("retry-percentile-badge");
    this.retryBtn = document.getElementById("retry-btn");
    this.shareBtn = document.getElementById("share-btn");

    // Viral URL Challenge & Meydan Okuma Referansları (P1)
    this.activeChallenge = this.parseURLChallenge();
    this.challengeBanner = document.getElementById("challenge-banner");
    this.challengerName = document.getElementById("challenger-name");
    this.challengeFloor = document.getElementById("challenge-floor");
    this.challengeTries = document.getElementById("challenge-tries");
    this.challengeDismissBtn = document.getElementById("challenge-dismiss-btn");
    this.gameToast = document.getElementById("game-toast");
    this.toastTimeout = null;
    this.lightningArcs = [];

    // HUD Hızlı Aksiyon & Kontrol Referansları (P0 Viral Kanca & Ses)
    this.hudChallengeBtn = document.getElementById("hud-challenge-btn");
    this.hudSoundBtn = document.getElementById("hud-sound-btn");
    this.hudSoundIcon = document.getElementById("hud-sound-icon");

    // Çekirdek Sistemler
    this.audio = new AudioManager();
    this.haptics = (typeof HapticsEngine !== "undefined") ? new HapticsEngine(this) : null;
    this.particles = new ParticleSystem();
    this.tower = new TowerManagerClass(CONFIG);
    this.cat = new Cat(CONFIG.CANVAS_WIDTH / 2, CONFIG.GROUND_Y - 45, CONFIG);
    this.input = new InputHandler(this.canvas, this.cat, this.audio, this, CONFIG);

    // Kule İlerleme Değişkenleri
    this.gameState = "IDLE"; // IDLE, FLOOR_TRANSITION, VICTORY_CLIMAX, SUCCESS, FAIL
    this.currentFloor = 1;
    this.victoryClimaxTimer = 0;

    // URL üzerinden temiz başlangıç kontrolü (?reset=1 veya ?clean=1)
    if (typeof window !== "undefined" && window.location && window.location.search) {
      if (window.location.search.includes("reset") || window.location.search.includes("clean")) {
        try {
          localStorage.removeItem("catdoor_best_floor");
          localStorage.removeItem("catdoor_nearmiss");
          localStorage.removeItem("catdoor_rage_attempts");
        } catch (e) {}
      }
    }

    // Mantıklı ve Temiz Sayaç Mimarisi (Mert & Burak - Seviye Standardı):
    // 1. BEST: Oyuncunun kuledeki rekor katı (1-5)
    this.bestFloor = parseInt(localStorage.getItem("catdoor_best_floor") || "1", 10);
    // 2. NEAR-MISS: Bu tırmanış koşusundaki toplam kıl payı skoru (0'dan başlar!)
    this.nearMisses = 0;
    // 3. TRY: O anki katın deneme sayısı (Her yeni kata geçildiğinde #1'den başlar!)
    this.stageAttempts = 1;
    this.rageAttempts = this.stageAttempts; // Geriye dönük tam uyumluluk

    // Kamera & Görsel Efektler
    this.cameraY = 0;
    this.cameraTargetY = 0;
    this.screenShake = 0;
    this.shakeDuration = 0;
    this.cameraZoom = 1.0;
    this.targetZoom = 1.0;
    this.timeScale = 1.0;
    this.realSlowMoTimer = 0;
    this.nearMissBadgeTimer = 0;
    this.nearMissFlashTimer = 0;
    this.freezeFrameTimer = 0; // 0.1s Near-Miss Freeze-Frame Heart Attack

    // Duyuru & Efekt Metinleri
    this.floatingBanner = null;
    this.lastTime = performance.now();

    // Ambient Cyber Dust & Starfield (Elite Parallax Atmosphere)
    this.ambientStars = [];
    for (let i = 0; i < 36; i++) {
      this.ambientStars.push({
        x: Math.random() * CONFIG.CANVAS_WIDTH,
        y: Math.random() * (CONFIG.TOTAL_STORY_FLOORS * CONFIG.FLOOR_HEIGHT + 600) - (CONFIG.TOTAL_STORY_FLOORS * CONFIG.FLOOR_HEIGHT),
        radius: 0.8 + Math.random() * 1.5,
        speed: 10 + Math.random() * 20,
        alpha: 0.15 + Math.random() * 0.45
      });
    }

    this.setupUI();
    this.updateHUD();
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);

    window.game = {
      cat: this.cat,
      tower: this.tower,
      engine: this,
      reset: () => this.reset(),
      state: () => this.gameState
    };
  }

  setupUI() {
    if (this.retryBtn) {
      this.retryBtn.addEventListener("click", () => {
        this.handlePlayAgain();
      });
    }
    if (this.shareBtn) {
      this.shareBtn.addEventListener("click", () => this.shareChallenge(this.shareBtn));
    }
    if (this.hudChallengeBtn) {
      this.hudChallengeBtn.addEventListener("click", () => this.shareChallenge(this.hudChallengeBtn));
    }
    if (this.hudSoundBtn) {
      this.updateSoundBtnUI();
      this.hudSoundBtn.addEventListener("click", () => {
        const isMuted = this.audio.toggleMute();
        this.updateSoundBtnUI();
        this.showToast(isMuted ? "🔇 Audio Muted" : "🔊 Audio Unmuted");
      });
    }
    if (this.retryContainer) {
      this.retryContainer.addEventListener("click", (e) => {
        if (e.target === this.retryContainer) {
          this.handlePlayAgain();
        }
      });
    }

    // P1: Challenge Banner Kapatma & Başlatma
    if (this.challengeDismissBtn) {
      this.challengeDismissBtn.addEventListener("click", () => {
        if (this.challengeBanner) this.challengeBanner.style.display = "none";
      });
    }
    this.initChallengeBanner();

    // Temiz Kayıt & Video Modu Sıfırlayıcısı (Mert & Burak):
    window.resetAllStats = () => {
      try {
        localStorage.clear();
      } catch (e) {}
      this.bestFloor = 1;
      this.nearMisses = 0;
      this.stageAttempts = 1;
      this.rageAttempts = 1;
      this.reset();
      this.updateHUD();
      this.showToast("✨ İstatistikler sıfırlandı! (STAGE 1/5 • TRY: #1)");
    };

    if (this.scoreBestDisplay) {
      this.scoreBestDisplay.style.cursor = "pointer";
      this.scoreBestDisplay.title = "Sıfırlamak için tıkla (Clean Recording Mode)";
      this.scoreBestDisplay.addEventListener("click", () => {
        if (window.resetAllStats) window.resetAllStats();
      });
    }

    window.addEventListener("keydown", (e) => {
      if (e.shiftKey && (e.key === "R" || e.key === "r")) {
        if (window.resetAllStats) window.resetAllStats();
      }
    });

    // Kule Merdiveninden Açılmış Katlara Doğrudan Atlama
    if (this.ladderNodes && this.ladderNodes.length) {
      this.ladderNodes.forEach(node => {
        node.addEventListener("click", () => {
          const f = parseInt(node.dataset.floor, 10);
          if (f <= this.bestFloor && f !== this.currentFloor && this.gameState !== "FLOOR_TRANSITION") {
            this.goToFloor(f);
            this.audio.playFloorClear(f);
          }
        });
      });
    }
  }

  updateHUD() {
    if (this.scorePassesDisplay) {
      this.scorePassesDisplay.textContent = this.currentFloor;
    }
    if (this.scoreBestDisplay) {
      this.scoreBestDisplay.textContent = this.bestFloor;
    }
    if (this.scoreNearmissDisplay) {
      this.scoreNearmissDisplay.textContent = this.nearMisses;
    }
    if (this.rageCounterDisplay) {
      this.rageCounterDisplay.textContent = `#${this.stageAttempts || 1}`;
    }
    if (this.floorDisplay) {
      const spec = CONFIG.FLOORS[this.currentFloor - 1] || { name: `AŞAMA ${this.currentFloor}` };
      this.floorDisplay.textContent = spec.name;
    }

    // Kule Merdiveni (Sağ Taraf Minimap) Güncellemesi
    if (this.ladderNodes && this.ladderNodes.length) {
      this.ladderNodes.forEach(node => {
        const f = parseInt(node.dataset.floor, 10);
        node.classList.remove("active", "cleared");
        if (f === this.currentFloor) {
          node.classList.add("active");
        } else if (f < this.currentFloor) {
          node.classList.add("cleared");
        }
      });
    }
  }

  // P1: Viral URL Challenge / Meydan Okuma Ayrıştırıcısı
  parseURLChallenge() {
    if (typeof window === "undefined" || !window.location || !window.location.search) return null;
    try {
      const params = new URLSearchParams(window.location.search);
      const challengerRaw = params.get("challenger") || params.get("c");
      if (!challengerRaw) return null;

      // XSS & uzunluk koruması
      const challenger = challengerRaw.replace(/[^\w\s\u00C0-\u017F-]/gi, "").trim().slice(0, 18) || "Rival";
      const floorVal = parseInt(params.get("floor") || params.get("f") || "4", 10);
      const targetFloor = Math.max(1, Math.min(5, isNaN(floorVal) ? 4 : floorVal));
      const triesVal = parseInt(params.get("tries") || params.get("t") || "28", 10);
      const targetTries = Math.max(1, isNaN(triesVal) ? 28 : triesVal);

      return {
        challenger,
        targetFloor,
        targetTries,
        isBeaten: false
      };
    } catch (e) {
      return null;
    }
  }

  initChallengeBanner() {
    if (!this.activeChallenge || !this.challengeBanner) return;
    if (this.challengerName) this.challengerName.textContent = this.activeChallenge.challenger;
    if (this.challengeFloor) this.challengeFloor.textContent = this.activeChallenge.targetFloor;
    if (this.challengeTries) this.challengeTries.textContent = this.activeChallenge.targetTries;
    this.challengeBanner.style.display = "flex";
  }

  updateChallengeBannerVictory() {
    if (!this.challengeBanner || !this.activeChallenge) return;
    this.challengeBanner.classList.add("beaten");
    const headline = this.challengeBanner.querySelector(".challenge-headline");
    const desc = this.challengeBanner.querySelector(".challenge-desc");
    if (headline) headline.innerHTML = `🏆 RECORD CRUSHED!`;
    if (desc) desc.innerHTML = `You beat <b>${this.activeChallenge.challenger}</b>'s Stage ${this.activeChallenge.targetFloor} challenge!`;
    this.particles.spawnVictoryFeast(CONFIG.CANVAS_WIDTH / 2, this.cameraY + 160);
    this.showToast(`🎉 You beat ${this.activeChallenge.challenger}'s challenge!`);
  }

  showToast(msg) {
    if (!this.gameToast) return;
    this.gameToast.textContent = msg;
    this.gameToast.style.display = "block";
    if (this.toastTimeout) clearTimeout(this.toastTimeout);
    this.toastTimeout = setTimeout(() => {
      if (this.gameToast) this.gameToast.style.display = "none";
    }, 2500);
  }

  updateSoundBtnUI() {
    if (!this.hudSoundIcon) return;
    const isMuted = this.audio && this.audio.isMuted;
    this.hudSoundIcon.textContent = isMuted ? "🔇" : "🔊";
    if (this.hudSoundBtn) {
      if (typeof this.hudSoundBtn.setAttribute === "function") {
        this.hudSoundBtn.setAttribute("aria-label", isMuted ? "Unmute Sound" : "Mute Sound");
      }
      if (this.hudSoundBtn.classList) {
        if (typeof this.hudSoundBtn.classList.toggle === "function") {
          this.hudSoundBtn.classList.toggle("muted", isMuted);
        } else if (isMuted && typeof this.hudSoundBtn.classList.add === "function") {
          this.hudSoundBtn.classList.add("muted");
        } else if (!isMuted && typeof this.hudSoundBtn.classList.remove === "function") {
          this.hudSoundBtn.classList.remove("muted");
        }
      }
    }
  }

  // P1: Kışkırtıcı Paylaşım Metni & Dinamik Meydan Okuma URL Üretimi
  shareChallenge(btnElement = null) {
    const origin = (typeof window !== "undefined" && window.location && window.location.origin) ? window.location.origin : "https://tiltopia.games";
    const pathname = (typeof window !== "undefined" && window.location && window.location.pathname) ? window.location.pathname : "/kedi-kapi";
    const shareUrl = `${origin}${pathname}?challenger=Player&floor=${this.currentFloor}&tries=${this.rageAttempts || 1}`;
    const text = `🐱 TILTOPIA CAT DOOR CHALLENGE!\nI reached Stage ${this.currentFloor} in ${this.rageAttempts || 1} tries! 😼\nThink you have faster reflexes than a cat?\n⚔️ Beat my score: ${shareUrl}\n#Tiltopia #CatDoor #IndieGame`;

    const targetBtn = btnElement || this.shareBtn;

    const handleSuccess = () => {
      if (targetBtn) {
        const orig = targetBtn.textContent;
        targetBtn.textContent = "⚡ COPIED!";
        targetBtn.classList.add("copied");
        setTimeout(() => {
          if (targetBtn) {
            targetBtn.textContent = orig;
            targetBtn.classList.remove("copied");
          }
        }, 1800);
      }
      this.showToast(`🏆 Challenge copied! Beat Stage ${this.currentFloor} in ${this.rageAttempts || 1} tries ⚡`);
      if (this.audio && !this.audio.isMuted) {
        this.audio.playCrownClink();
      }
    };

    if (typeof navigator !== "undefined" && navigator.share) {
      navigator.share({
        title: "Cat Door: Tower Climb",
        text: text,
        url: shareUrl
      }).then(handleSuccess).catch((err) => {
        if (err && err.name !== "AbortError") {
          this.copyToClipboard(text, handleSuccess);
        }
      });
    } else {
      this.copyToClipboard(text, handleSuccess);
    }
  }

  copyToClipboard(text, handleSuccess) {
    if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(handleSuccess).catch(() => {
        this.fallbackCopy(text);
        handleSuccess();
      });
    } else {
      this.fallbackCopy(text);
      handleSuccess();
    }
  }

  fallbackCopy(text) {
    try {
      if (typeof document === "undefined") return;
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
    } catch (e) {}
  }

  // P2: Çatallanan Mikro Şimşek Koordinat Üreteci
  generateJaggedLightning(start, end, segments = 5) {
    const points = [start];
    const dx = (end.x - start.x) / segments;
    const dy = (end.y - start.y) / segments;
    for (let i = 1; i < segments; i++) {
      const normalX = -dy;
      const normalY = dx;
      const len = Math.hypot(normalX, normalY) || 1;
      const offset = (Math.random() - 0.5) * 22;
      points.push({
        x: start.x + dx * i + (normalX / len) * offset,
        y: start.y + dy * i + (normalY / len) * offset
      });
    }
    points.push(end);
    return points;
  }

  triggerShake(intensity, duration) {
    this.screenShake = intensity;
    this.shakeDuration = duration;
  }

  // 1. ZİRVE: KAT ATLAMA BAŞARISI (Yukarı Fırlama & Kamera Tırmanışı!)
  triggerFloorClear() {
    if (this.gameState === "FLOOR_TRANSITION" || this.gameState === "SUCCESS") return;

    const clearedFloor = this.currentFloor;
    const door = this.tower.getCurrentDoor();
    const c = this.cat.getCenter();

    // 1. Alt Katı Anında Mühürle & Kilitli Çelik Izgarayı Kapat (CLANG-LATCH!)
    this.tower.sealFloor(clearedFloor);
    this.audio.playGrateSlam();

    // Otomatik geçiş hatasını önlemek için bayrakları sıfırla
    door.wasOpenOnCatEntry = false;
    this.cat.isLaunched = false;
    this.cat.launchTime = 0;

    // 2. Kıl Payı Başarılı Geçiş (Close-Call Squeeze Success) Kontrolü
    const isCloseCall = door.isWarning || door.isSnapping || Math.abs(c.x - door.leftPostX) < 14 || Math.abs(c.x - door.rightPostX) < 14;
    if (isCloseCall) {
      this.timeScale = 0.25;
      this.realSlowMoTimer = 0.22;
      this.targetZoom = 1.10;
      this.triggerShake(6.5, 0.22);
      this.audio.playCloseCall();
      this.particles.spawnSparks(door.centerX, door.y);
      this.nearMisses++;
      localStorage.setItem("catdoor_nearmiss", this.nearMisses.toString());
    } else {
      this.targetZoom = 1.05;
      this.triggerShake(4.5, 0.18);
      this.audio.playFloorClear(clearedFloor);
      this.audio.playCatHappyPurr();
    }

    if (this.haptics) {
      this.haptics.floorClear();
    }

    this.cat.mode = "VICTORY_SPIN";
    this.cat.spinAngle = 0;
    this.cat.spinVelocity = Math.PI * 5;

    // Kedi üst kata doğru kontrollü ve pürüzsüz bir zafer sıçraması yapar (aşırı fırlama & geri düşme yok!)
    this.cat.pointList.forEach(pt => {
      pt.vx = (CONFIG.CANVAS_WIDTH / 2 - pt.x) * 3;
      pt.vy = -280;
    });

    this.particles.spawnVictoryFeast(door.centerX, door.y - 65);

    // P1: Challenge Hedefi Aşma Kontrolü
    if (this.activeChallenge && !this.activeChallenge.isBeaten) {
      if (clearedFloor >= this.activeChallenge.targetFloor) {
        this.activeChallenge.isBeaten = true;
        this.updateChallengeBannerVictory();
      }
    }

    // Kule Zirvesi (Aşama 5 Kraliyet Çatısı Şampiyonluğu & 1.8s Altın Konfeti Zafer Kutlaması)
    if (clearedFloor >= CONFIG.TOTAL_STORY_FLOORS) {
      this.gameState = "VICTORY_CLIMAX";
      this.victoryClimaxTimer = 1.8;
      this.currentFloor = CONFIG.TOTAL_STORY_FLOORS;
      this.bestFloor = CONFIG.TOTAL_STORY_FLOORS;
      localStorage.setItem("catdoor_best_floor", "5");

      if (this.audio) {
        if (this.audio.playCrownClink) this.audio.playCrownClink();
        if (this.audio.playPopCork) this.audio.playPopCork();
        if (this.audio.playCatHappyPurr) this.audio.playCatHappyPurr();
      }

      if (this.haptics) {
        this.haptics.victory();
      }

      this.floatingBanner = {
        title: "👑 ROYAL SALMON KING! 👑",
        subtitle: "YOU CONQUERED THE TOWER!",
        color: "#ffd700",
        alpha: 1.0
      };

      this.updateHUD();
      return;
    }

    // Kat Atlama Geçişi
    this.gameState = "FLOOR_TRANSITION";
    const nextFloor = clearedFloor + 1;
    const nextSpec = CONFIG.FLOORS[nextFloor - 1];

    let bannerTitle = `STAGE ${nextFloor} UNLOCKED!`;
    let bannerSubtitle = nextSpec ? nextSpec.subtitle : "Keep climbing!";
    let bannerColor = "#00ff88";

    // P0 Dopamin: Kat Evrim Aksesuarı Açılma Kutlaması
    if (nextFloor === 3) {
      bannerTitle = "🍣 SALMON NIGIRI UNLOCKED!";
      bannerSubtitle = "Stage 03: Laser Guillotine Hall";
      bannerColor = "#ff0055";
      if (this.audio && this.audio.playCrownClink) this.audio.playCrownClink();
    } else if (nextFloor === 4) {
      bannerTitle = "🦸 HERO CAPE UNLOCKED!";
      bannerSubtitle = "Stage 04: Gale Windy Balcony";
      bannerColor = "#00e5ff";
      if (this.audio && this.audio.playCrownClink) this.audio.playCrownClink();
    } else if (nextFloor === 5) {
      bannerTitle = "👑 ROYAL CROWN UNLOCKED!";
      bannerSubtitle = "Final Ascent: The Steampunk Vault";
      bannerColor = "#ffd700";
      if (this.audio && this.audio.playCrownClink) this.audio.playCrownClink();
    }

    if (isCloseCall) {
      bannerTitle = `⚡ CLOSE CALL! +500 ⚡`;
    }

    this.floatingBanner = {
      title: bannerTitle,
      subtitle: bannerSubtitle,
      color: bannerColor,
      alpha: 1.0
    };

    // Kamerayı anında yukarıdaki kata doğru kaydırmaya başla (Asansör hissi!)
    this.cameraTargetY = (nextFloor - 1) * (-CONFIG.FLOOR_HEIGHT) || 0;
    this.transitionNextFloor = nextFloor;
    this.transitionMaxTimer = 1.6; // Parabolik fiziksel iniş güvenlik zaman aşımı
  }

  // 2. ZİRVE: NEAR-MISS (Milimetrik Giyotin / Kuyruk Kıstırma)
  triggerNearMiss() {
    if (this.gameState === "FAIL" || this.cat.isNearMissTriggered) return;
    this.gameState = "FAIL";
    this.cat.isNearMissTriggered = true;
    this.stageAttempts++;
    this.rageAttempts = this.stageAttempts;

    this.timeScale = 0.25;
    this.realSlowMoTimer = 0.35;
    this.nearMissBadgeTimer = 1.8;
    this.nearMissFlashTimer = 0.28;
    this.freezeFrameTimer = 0.12; // 0.1s Dramatik Donma (Freeze Frame)
    this.cat.isEyePopped = true;
    this.cat.eyePopTimer = 0.65;
    this.targetZoom = 1.22; // Makro zoom
    this.triggerShake(7.5, 0.26);
    if (this.haptics) this.haptics.nearMiss();

    if (this.audio && this.audio.playHeartThump) this.audio.playHeartThump();
    this.audio.playMagnetSnap();
    this.audio.playNearMiss();
    this.audio.playCatBonkYowl();

    const door = this.tower.getCurrentDoor();
    this.particles.spawnSparks(door.centerX, door.y);
    // P2: Yüksek voltajlı elektrik kıvılcımları & çatallanan şimşek yayları
    this.particles.spawnElectricSparks(door.centerX, door.y);
    const c = this.cat.getCenter();
    this.lightningArcs = [];
    for (let i = 0; i < 4; i++) {
      const start = { x: c.x + (Math.random() - 0.5) * 18, y: c.y + (Math.random() - 0.5) * 18 };
      const end = { x: door.centerX + (Math.random() - 0.5) * (door.doorWidth || 80), y: door.y + (Math.random() - 0.5) * 20 };
      this.lightningArcs.push(this.generateJaggedLightning(start, end, 5));
    }
    // P2: HUD Near-Miss Nabız Animasyonu
    if (this.scoreNearmissDisplay) {
      this.scoreNearmissDisplay.classList.remove("pulse");
      void this.scoreNearmissDisplay.offsetWidth;
      this.scoreNearmissDisplay.classList.add("pulse");
    }
    door.applyImpactShudder(1.8);

    // Kedi kapıya çarpınca kendi kat zeminine doğru seker!
    this.startFloorBonkRebound();
    this.nearMisses++;
    this.updateHUD();
  }

  // 3. ZİRVE: FLAP BONK (DOINK! Kilitli Kapağa Kafa Çarpma)
  triggerBonk() {
    if (this.gameState === "FAIL") return;
    this.gameState = "FAIL";
    this.stageAttempts++;
    this.rageAttempts = this.stageAttempts;

    this.audio.playMetallicBonk();
    this.audio.playCatBonkYowl();
    this.triggerShake(9.0, 0.30);
    if (this.haptics) this.haptics.bonk();

    const door = this.tower.getCurrentDoor();
    door.applyImpactShudder(2.0);
    this.particles.spawnSparks(this.cat.points.head.x, this.cat.points.head.y);

    this.startFloorBonkRebound();
    this.updateHUD();
  }

  // Mevcut Kat Zeminine Sekme & Çakılma (Asla Alt Katlara Düşmez — Kamera Sabit Kalır!)
  startFloorBonkRebound() {
    this.audio.playFallWhistle(0.8);
    this.cat.mode = "TUMBLING";
    this.cat.tumbleAngle = 0;
    this.cat.tumbleTimer = 0.45;

    // Kediyi mantıklı bir kavisle KENDİ KATININ başlangıç tüneğine doğru yönlendirir
    const c = this.cat.getCenter();
    const targetStartX = CONFIG.CANVAS_WIDTH / 2;
    const toCenterX = (targetStartX - c.x);
    const returnVx = Math.max(-120, Math.min(120, toCenterX * 2.2));
    this.cat.tumbleVelocity = (returnVx >= 0 ? 1 : -1) * 12.0;

    this.cat.pointList.forEach(pt => {
      pt.vx = returnVx + (Math.random() - 0.5) * 20;
      pt.vy = 260; // Yumuşak ve doğal iniş
    });

    const spec = CONFIG.FLOORS[this.currentFloor - 1] || { name: `STAGE ${this.currentFloor}` };
    this.floatingBanner = {
      title: `💥 STAGE ${this.currentFloor} BONK!`,
      subtitle: `Try #${this.stageAttempts} • Auto-Resetting...`,
      color: "#ff0055",
      alpha: 1.0
    };
  }

  // Zemin Çakılması (Mevcut kat zemininde lokal çakılma — Modal Popup Yok!)
  triggerGroundFail() {
    if (this.gameState === "FAIL") return;
    this.gameState = "FAIL";
    this.stageAttempts++;
    this.rageAttempts = this.stageAttempts;
    this.audio.playTowerSplat();
    this.triggerShake(9.5, 0.35);
    if (this.haptics) this.haptics.bonk();
    this.cat.mode = "SPLAT";
    const platformY = CONFIG.GROUND_Y - (this.currentFloor - 1) * CONFIG.FLOOR_HEIGHT;
    this.cat.settleSplat(this.cat.getCenter().x, platformY);

    this.floatingBanner = {
      title: `SPLAT!`,
      subtitle: `Try #${this.stageAttempts} • Tap to Launch`,
      color: "#ff0055",
      alpha: 1.0
    };

    // 0.50 sn sonra kedi otomatik olarak pıt diye ayağa kalkar (Kesintisiz Arcade Akışı)
    setTimeout(() => {
      if (this.gameState === "FAIL") {
        this.cat.settleOnFloor(this.currentFloor);
        this.gameState = "IDLE";
        this.updateHUD();
      }
    }, 500);
    this.updateHUD();
  }

  finishVictoryClimax() {
    this.victoryClimaxTimer = 0;
    this.gameState = "SUCCESS";
    this.showRetryModal("👑 TOWER CHAMPION!", "The Royal Salmon Crown is yours!");
  }

  // Kat Geçişi Hızlı İniş (Tap-to-Drop: 1.6s beklemeyi anında 0.1s'ye indirip tüneğe oturtur)
  fastPerchDrop() {
    if (this.gameState !== "FLOOR_TRANSITION" || !this.transitionNextFloor) return;
    const nextFloor = this.transitionNextFloor;
    this.currentFloor = nextFloor;
    if (this.currentFloor > this.bestFloor) {
      this.bestFloor = this.currentFloor;
      localStorage.setItem("catdoor_best_floor", this.bestFloor.toString());
    }
    this.tower.currentFloor = this.currentFloor;
    this.cat.settleOnFloor(nextFloor);
    this.cameraTargetY = (nextFloor - 1) * (-CONFIG.FLOOR_HEIGHT) || 0;
    this.cameraY = this.cameraTargetY;
    this.gameState = "IDLE";
    this.transitionNextFloor = null;
    this.transitionMaxTimer = 0;
    this.tower.doors.forEach(d => { d.wasOpenOnCatEntry = false; });
    this.cat.isLaunched = false;
    this.cat.mode = "IDLE";
    if (this.audio) this.audio.playBoing();
    if (this.haptics) this.haptics.pull();
    this.updateHUD();
  }

  showRetryModal(title, subtitle) {
    if (!this.retryContainer) return;
    if (this.retryTitle) this.retryTitle.textContent = title;
    if (this.retrySubtitle) this.retrySubtitle.textContent = subtitle;
    if (this.retryFloorBadge) this.retryFloorBadge.textContent = `STAGE 0${this.currentFloor}`;
    if (this.retryPercentileBadge) {
      this.retryPercentileBadge.style.display = "none";
    }
    this.retryContainer.classList.add("visible");
  }

  // Belirli Bir Kata Gitme / Atlama
  goToFloor(floorNum) {
    this.currentFloor = floorNum;
    this.tower.currentFloor = floorNum;
    // Geçilmiş alt katları mühürle (delik kalmasın)
    for (let f = 1; f < floorNum; f++) {
      this.tower.sealFloor(f);
    }
    const curDoor = this.tower.getCurrentDoor();
    if (curDoor) {
      curDoor.isSealed = false;
      curDoor.cycleTimer = 0;
      curDoor.isOpen = false;
      curDoor.isWarning = false;
      curDoor.isSnapping = false;
      curDoor.flapAngle = 0;
      curDoor.targetFlapAngle = 0;
      curDoor.fanAngle = 0;
      curDoor.hasCollidedBlade = false;
      curDoor.wasOpenOnCatEntry = false;
    }
    this.cat.settleOnFloor(floorNum);
    this.cameraTargetY = (floorNum - 1) * (-CONFIG.FLOOR_HEIGHT) || 0;
    this.cameraY = this.cameraTargetY;
    this.gameState = "IDLE";
    this.victoryClimaxTimer = 0;
    this.transitionNextFloor = null;
    this.timeScale = 1.0;
    this.realSlowMoTimer = 0;
    this.nearMissBadgeTimer = 0;
    this.nearMissFlashTimer = 0;
    this.freezeFrameTimer = 0; // 0.1s Near-Miss Freeze-Frame Heart Attack
    this.screenShake = 0;
    this.targetZoom = 1.0;
    this.cameraZoom = 1.0;
    this.floatingBanner = null;
    if (this.splatRecoveryTimer) {
      clearTimeout(this.splatRecoveryTimer);
      this.splatRecoveryTimer = null;
    }
    if (this.retryContainer) this.retryContainer.classList.remove("visible");
    this.updateHUD();
  }

  // Zafer Ekranı veya Ara Kat Yeniden Oyna Butonu Yönetimi
  handlePlayAgain() {
    if (this.retryContainer) {
      this.retryContainer.classList.remove("visible");
    }
    if (this.audio) this.audio.playInstantRestart();
    // Eğer kule tamamlandıysa (5. Kat) veya oyun SUCCESS modundaysa,
    // tüm kuleyi sıfırlayıp 1. Kattan (Bodrum Girişi) başlatır!
    if (this.currentFloor >= CONFIG.TOTAL_STORY_FLOORS || this.gameState === "SUCCESS") {
      this.reset();
    } else {
      this.retryCurrentFloor();
    }
  }

  // Mevcut Aşamayı Sıfır Gecikmeyle Yeniden Başlatma (Hot Retry)
  retryCurrentFloor() {
    this.goToFloor(this.currentFloor);
  }

  // Tüm Kuleyi Sıfırlama (Hard Reset)
  reset() {
    this.tower.reset();
    this.stageAttempts = 1;
    this.rageAttempts = 1;
    this.nearMisses = 0;
    this.goToFloor(1);
  }

  update(rawDt) {
    if (this.realSlowMoTimer > 0) {
      this.realSlowMoTimer -= rawDt;
      if (this.realSlowMoTimer <= 0) {
        this.timeScale = 1.0;
        this.targetZoom = 1.0;
      }
    }
    if (this.freezeFrameTimer > 0) {
      this.freezeFrameTimer -= rawDt;
    }
    if (this.nearMissBadgeTimer > 0) {
      this.nearMissBadgeTimer -= rawDt;
    }
    if (this.nearMissFlashTimer > 0) {
      this.nearMissFlashTimer -= rawDt;
    }

    // 0.1s Freeze Frame: Zaman neredeyse durur (0.02x mikro akış), kalp atışı çalınır
    const scaledDt = (this.freezeFrameTimer > 0) ? (rawDt * 0.02) : (rawDt * this.timeScale);

    // Kamera Sarsıntısı & Zoom
    if (this.shakeDuration > 0) {
      this.shakeDuration -= rawDt;
      if (this.shakeDuration <= 0) this.screenShake = 0;
    }
    this.cameraZoom += (this.targetZoom - this.cameraZoom) * Math.min(1, rawDt * 10);

    // Kule Kamera Takibi (Kamera daima mevcut katın platform seviyesinde stabil kalır)
    this.cameraTargetY = (this.currentFloor - 1) * (-CONFIG.FLOOR_HEIGHT);
    this.cameraY += (this.cameraTargetY - this.cameraY) * Math.min(1, rawDt * 8);

    // Alt Sistem Güncellemeleri
    this.tower.update(scaledDt, this.audio, this.particles);
    this.particles.update(scaledDt);
    this.input.update(rawDt);

    if (this.floatingBanner && this.floatingBanner.alpha > 0) {
      this.floatingBanner.alpha -= rawDt * 0.45;
      if (this.floatingBanner.alpha <= 0) this.floatingBanner = null;
    }

    // Ambient Dust Takibi
    if (this.ambientStars) {
      this.ambientStars.forEach(s => {
        s.y -= s.speed * rawDt;
        const topBound = this.cameraY - 200;
        const botBound = this.cameraY + CONFIG.CANVAS_HEIGHT + 200;
        if (s.y < topBound) s.y = botBound;
      });
    }

    // 0. KAT 5 KRALİYET ZİRVE ZAFER KUTLAMASI (2.2s Altın Konfeti Yağmuru & Gururlu Kedi Duruşu)
    if (this.gameState === "VICTORY_CLIMAX") {
      this.victoryClimaxTimer -= rawDt;
      this.particles.spawnGoldenConfettiRain(this.cameraY);

      this.cat.update(scaledDt);
      const catCenter = this.cat.getCenter();
      if (Math.random() < 0.28) {
        this.particles.spawnPurrHeart(catCenter.x, catCenter.y);
      }

      // Zafer taklası tamamlanınca gururlu mutlu feasting duruşuna geç
      if (this.victoryClimaxTimer < 1.7 && this.cat.mode === "VICTORY_SPIN") {
        this.cat.mode = "FEASTING";
      }

      if (this.victoryClimaxTimer <= 0) {
        this.finishVictoryClimax();
      }
      return;
    }

    // 0. TELEPORTASYONSUZ KESİNTİSİZ KAT GEÇİŞİ VE ÜST KATA FİZİKSEL İNİŞ
    if (this.gameState === "FLOOR_TRANSITION" && this.transitionNextFloor) {
      if (this.transitionMaxTimer > 0) this.transitionMaxTimer -= rawDt;
      const nextFloor = this.transitionNextFloor;
      const nextPlatformY = CONFIG.GROUND_Y - (nextFloor - 1) * CONFIG.FLOOR_HEIGHT;
      const targetPerchY = nextPlatformY - 45;

      this.cat.update(scaledDt);
      const catCenter = this.cat.getCenter();

      // Üst kata kontrollü iniş: Kedi tüneğe ulaştığında veya inişteyken pürüzsüz konar
      if ((catCenter.y >= targetPerchY - 20 && this.cat.points.body_bottom.vy >= 0 && this.transitionMaxTimer < 1.4) || (catCenter.y <= targetPerchY + 10 && this.transitionMaxTimer < 1.0) || this.transitionMaxTimer <= 0) {
        this.currentFloor = nextFloor;
        if (this.currentFloor > this.bestFloor) {
          this.bestFloor = this.currentFloor;
          localStorage.setItem("catdoor_best_floor", this.bestFloor.toString());
        }
        this.tower.currentFloor = this.currentFloor;
        this.cat.landOnFloor(this.currentFloor);
        this.gameState = "IDLE";
        this.targetZoom = 1.0;
        this.transitionNextFloor = null;

        // BİR SONRAKİ KATI OTOMATİK GEÇME HATASINI KESİN OLARAK ENGELLE:
        this.tower.doors.forEach(d => { d.wasOpenOnCatEntry = false; });
        this.cat.isLaunched = false;
        this.cat.mode = "IDLE";
        this.cat.launchTime = 0;
        this.stageAttempts = 1;
        this.rageAttempts = 1;

        this.updateHUD();
        this.audio.playBoing();
        this.particles.spawnSparks(CONFIG.CANVAS_WIDTH / 2, nextPlatformY);
        return; // BU KAREDE İŞLEMİ ANINDA BİTİR!
      }
      return; // Kat geçişi devam ederken kapı kontrollerini çalıştırma!
    }

    // Aktif katın kapısı güncel kattan çekilir
    const door = this.tower.getCurrentDoor();
    const c = this.cat.getCenter();
    const doorTop = door.y - door.height;

    // 1. Matematiksel Açıklık Koridoru: Kedinin yatayda kapı direkleri arasında olması
    const inApertureX = (c.x >= door.leftPostX - 14 && c.x <= door.rightPostX + 16);

    // 2. Kapı Eşiği Bölgesi & Hacim Sıkışması ("Cats are liquid" hacim korunumu)
    // KRİTİK: inDoorZone SADECE kapı açıklığı hizasında (inApertureX) aktiftir;
    // Açık balkon ve yan duvar koridorlarında havada hayalet bonk oluşması kesinlikle engellenir!
    const inDoorZone = this.cat.isLaunched && inApertureX && Math.abs(c.y - door.y) < 46;
    this.cat.isSqueezing = inDoorZone && inApertureX;

    if (inDoorZone && inApertureX && door.isOpen) {
      door.wasOpenOnCatEntry = true;
    }

    this.cat.update(scaledDt);

    // Kat 4 Özel Mekaniği: Çapraz Fırtına Rüzgarı (-520G Kuvvet)
    const curFloorSpec = CONFIG.FLOORS[this.currentFloor - 1];
    if (curFloorSpec && (curFloorSpec.mechanic === "WIND" || curFloorSpec.mechanic === "WIND_BOUNCE") && this.cat.isLaunched && this.cat.mode === "LAUNCHED") {
      const windForceVal = curFloorSpec.windForce || -520;
      this.cat.pointList.forEach(pt => {
        pt.vx += windForceVal * scaledDt;
      });
      // Rüzgar hava akımı sürtünme parçacıkları
      if (Math.random() < 0.6) {
        this.particles.spawnWindSlipstream(c.x, c.y);
      }
    }

    const collisionResult = door.checkCollision(this.cat, scaledDt, this.audio, this.particles);

    // Mekanizmaya Özel Çarpışmalar (Bıçak ve İris Çarpışması)
    if (collisionResult === "BONK_BLADE" || collisionResult === "BONK_IRIS") {
      if (this.gameState === "IDLE") {
        this.triggerBonk();
        return;
      }
    } else if (collisionResult === "NEAR_MISS_IRIS" || collisionResult === "NEAR_MISS_BLADE" || collisionResult === "NEAR_MISS_GUILLOTINE") {
      if (this.gameState === "IDLE") {
        this.triggerNearMiss();
        return;
      }
    }

    // 1. KAT ATLAMA BAŞARISI (SADECE VE SADECE O KATTA AKTİF VE BİLİNÇLİ FIRLATILMIŞSA ÇALIŞIR!)
    const isActivelyLaunched = (this.cat.isLaunched && this.cat.mode === "LAUNCHED" && (this.cat.launchTime || 0) > 0.12);
    const isPassingUpward = (this.cat.points.head.vy < 0);
    // 4. Kat Özel Trickshot Kuralı: Bouncera çarpmadan doğrudan kapıdan geçilemez!
    const bouncerSatisfied = (curFloorSpec.mechanic !== "WIND_BOUNCE" || door.hasBouncedThisLaunch);

    let hasClearedCurrentDoor = false;
    let doorOpenSatisfied = false;

    if (curFloorSpec.mechanic === "ROTATING_FAN") {
      // 2. KAT: DÖNEN CAM KAPI GEÇİŞ STANDARDI (MERT & BURAK - POLAR AÇISAL KORİDOR)
      const fanTopY = door.y - (curFloorSpec.fanRadius || 64);
      const isPastFan = (c.y < door.y - 2 || this.cat.points.head.y < fanTopY);
      const zeroContact = (!door.hasCollidedBlade && !this.cat.isGlassSmushed);
      doorOpenSatisfied = zeroContact && (door.wasOpenOnCatEntry || door.isOpen);
      hasClearedCurrentDoor = isPastFan && zeroContact;
    } else {
      // DİĞER STANDART VE ÖZEL KAPILAR:
      // KRİTİK DOĞRULAMA (Senaryo 2): Kedi kapıdan geçerken kapı kapanmışsa (isSnapping veya !door.isOpen),
      // kedi üst kata GEÇEMEZ; kapak kediye çarpar ve KESİN NEAR-MISS tetiklenir!
      const allPointsCleared = (this.cat.points.body_bottom.y < door.y - 4);

      if (door.isSnapping || (!door.isOpen && !allPointsCleared)) {
        if (inDoorZone && this.gameState === "IDLE") {
          this.triggerNearMiss();
          return;
        }
        doorOpenSatisfied = false;
      } else {
        doorOpenSatisfied = door.wasOpenOnCatEntry && door.isOpen;
      }

      hasClearedCurrentDoor = allPointsCleared && (c.y > door.y - CONFIG.FLOOR_HEIGHT);
    }

    const isClearValid = isActivelyLaunched && hasClearedCurrentDoor && inApertureX && doorOpenSatisfied && isPassingUpward && bouncerSatisfied;

    if (isClearValid && this.gameState === "IDLE") {
      this.triggerFloorClear();
      return;
    }

    // 2. KAPI ENGELİ KONTROLÜ (Kapalıyken veya Pervaneye/Giyotine Çarpma — Anti-Ghosting)
    if (inDoorZone && this.gameState === "IDLE") {
      if (curFloorSpec.mechanic === "ROTATING_FAN") {
        // Dönen kapı kapalıyken (kırmızı/süpüren engel) alt giriş portuna çarpma
        if (!door.isOpen && !door.wasOpenOnCatEntry && c.y > door.y) {
          this.triggerBonk();
          return;
        }
      } else {
        if (!door.isOpen) {
          const ptsAbove = this.cat.pointList.filter(pt => pt.y < door.y).length;
          const edgeProximity = Math.min(Math.abs(c.x - door.leftPostX), Math.abs(c.x - door.rightPostX));
          // Kıl payı eşiği: 14px pervaz teğeti (10-14px standardı), kapı kapanırken içeride kalma veya başın kapıyı aşmış olması
          const isNearMiss = door.wasOpenOnCatEntry || door.isSnapping || (door.isWarning && ptsAbove >= 1) || edgeProximity < 14;
          if (isNearMiss) {
            this.triggerNearMiss();
            return;
          } else {
            this.triggerBonk();
            return;
          }
        }
      }
    }

    // Kat 4 Trickshot Kıl Payı: Bouncer'dan sekip kapı kapalıyken veya pervaz dışına toslama (14px standardı)
    if (curFloorSpec && curFloorSpec.mechanic === "WIND_BOUNCE" && door.hasBouncedThisLaunch && this.gameState === "IDLE") {
      if (Math.abs(c.y - door.y) < 16) {
        const isOutsideAperture = (c.x < door.leftPostX || c.x > door.rightPostX);
        if (!door.isOpen || isOutsideAperture) {
          const edgeProximity = Math.min(Math.abs(c.x - door.leftPostX), Math.abs(c.x - door.rightPostX));
          if (edgeProximity < 14) {
            this.triggerNearMiss();
            return;
          }
        }
      }
    }

    // 3. YERE İNME / YETERSİZ GÜÇ KONTROLÜ (Gereksiz Fail Yok — Anında Yeniden Atış!)
    if (this.cat.isLaunched && this.cat.mode === "LAUNCHED" && (this.cat.launchTime || 0) > 0.25) {
      const platformY = CONFIG.GROUND_Y - (this.currentFloor - 1) * CONFIG.FLOOR_HEIGHT;
      if (c.y >= platformY - 55 && this.cat.points.body_bottom.vy >= 0) {
        if (this.gameState === "IDLE") {
          this.audio.playBoing();
          this.cat.settleOnFloor(this.currentFloor);
          this.floatingBanner = {
            title: "PULL HARDER! 😼",
            subtitle: "Pull back further to clear the door!",
            color: "#ffd700",
            alpha: 1.0
          };
        }
      }
    }

    // 4. MEVCUT KAT ZEMİNİNE ÇAKILMA & HIZLI OTOMATİK AYAĞA KALKIŞ (MODAL YOK — SIFIR KESİNTİ!)
    const currentPlatformY = CONFIG.GROUND_Y - (this.currentFloor - 1) * CONFIG.FLOOR_HEIGHT;
    if ((this.cat.mode === "TUMBLING" || this.cat.mode === "SPLAT") && c.y >= currentPlatformY - 45) {
      if (!this.splatRecoveryTimer && this.gameState === "FAIL") {
        this.audio.playTowerSplat();
        this.triggerShake(8.5, 0.28);
        this.cat.mode = "SPLAT";
        this.cat.settleSplat(c.x, currentPlatformY);

        // 0.45 sn sonra kedi otomatik olarak pıt diye ayağa kalkıp tüneğe oturur
        this.splatRecoveryTimer = setTimeout(() => {
          this.splatRecoveryTimer = null;
          if (this.gameState === "FAIL") {
            this.cat.settleOnFloor(this.currentFloor);
            this.gameState = "IDLE";
            this.updateHUD();
          }
        }, 450);
      }
    }
  }

  render() {
    this.ctx.save();

    // Kamera Dönüşümü (Kule Yükseklik Takibi)
    const zx = CONFIG.CANVAS_WIDTH / 2;
    const zy = CONFIG.CANVAS_HEIGHT / 2;
    this.ctx.translate(zx, zy);
    this.ctx.scale(this.cameraZoom, this.cameraZoom);

    const sx = this.screenShake > 0 ? (Math.random() - 0.5) * this.screenShake : 0;
    const sy = this.screenShake > 0 ? (Math.random() - 0.5) * this.screenShake : 0;
    this.ctx.translate(-zx + sx, -zy + sy);

    // Kamera Y Kaydırması
    this.ctx.translate(0, -this.cameraY);

    this.ctx.clearRect(0, this.cameraY - 200, CONFIG.CANVAS_WIDTH, CONFIG.CANVAS_HEIGHT + 400);

    // 1. Kule Parallax Arka Planı
    this.drawTowerBackground();

    // 2. Kule Katları, Platformları & Kapıları
    this.tower.draw(this.ctx, this.particles, this.cameraY);

    // 3. Sapan & Kedi
    this.input.drawSlingshot(this.ctx);
    this.cat.draw(this.ctx);
    this.particles.draw(this.ctx);

    // 4. Sıfır Metin Onboarding Jesti (0-2 Saniye Görsel Affordance)
    this.input.drawOnboardingHint(this.ctx);

    // 5. Near-Miss Yüksek Voltaj Şimşek Parlaması & Çatallanan Elektrik Yayları (P2)
    if (this.nearMissFlashTimer > 0) {
      const flashAlpha = Math.min(1.0, this.nearMissFlashTimer * 3.5) * 0.38;
      this.ctx.fillStyle = `rgba(255, 230, 0, ${flashAlpha})`;
      this.ctx.fillRect(0, this.cameraY - 100, CONFIG.CANVAS_WIDTH, CONFIG.CANVAS_HEIGHT + 200);

      // P2: Mikro Sarı Şimşek Çatlamaları (Branching Lightning Arcs)
      if (this.lightningArcs && this.lightningArcs.length) {
        this.ctx.save();
        this.ctx.shadowColor = "#ffff00";
        this.ctx.shadowBlur = 14;
        this.ctx.strokeStyle = "#ffee00";
        this.ctx.lineWidth = 2.4;
        this.lightningArcs.forEach(arc => {
          this.ctx.beginPath();
          arc.forEach((pt, idx) => {
            if (idx === 0) this.ctx.moveTo(pt.x, pt.y);
            else this.ctx.lineTo(pt.x, pt.y);
          });
          this.ctx.stroke();
        });
        // Akkor Beyaz Çekirdek
        this.ctx.strokeStyle = "#ffffff";
        this.ctx.lineWidth = 1.0;
        this.lightningArcs.forEach(arc => {
          this.ctx.beginPath();
          arc.forEach((pt, idx) => {
            if (idx === 0) this.ctx.moveTo(pt.x, pt.y);
            else this.ctx.lineTo(pt.x, pt.y);
          });
          this.ctx.stroke();
        });
        this.ctx.restore();
      }
    }

    // ⚡ VİRAL: 0.1s Near-Miss Freeze-Frame Anime Hız Çizgileri (Dramatic Speed Lines)
    if (this.freezeFrameTimer > 0) {
      const c = this.cat.getCenter();
      this.ctx.save();
      this.ctx.strokeStyle = "rgba(255, 255, 255, 0.50)";
      this.ctx.lineWidth = 2.0;
      for (let i = 0; i < 16; i++) {
        const a = (i * Math.PI * 2) / 16 + (Math.sin(Date.now() * 0.05 + i) * 0.08);
        const r1 = 55 + (i % 2) * 15;
        const r2 = 280 + (i % 3) * 45;
        this.ctx.beginPath();
        this.ctx.moveTo(c.x + Math.cos(a) * r1, c.y + Math.sin(a) * r1);
        this.ctx.lineTo(c.x + Math.cos(a) * r2, c.y + Math.sin(a) * r2);
        this.ctx.stroke();
      }
      this.ctx.restore();
    }

    // 6. Near-Miss Rozeti (⚡ 1 MILIMETRE! ⚡)
    if (this.nearMissBadgeTimer > 0) {
      const door = this.tower.getCurrentDoor();
      this.drawNearMissBadge(door.centerX, door.y - 88);
    }

    // 6.5. Kat 5 Kraliyet Şampiyonluk Altın Işık Hüzmeleri (Victory Climax Golden God Rays)
    if (this.gameState === "VICTORY_CLIMAX") {
      const c = this.cat.getCenter();
      this.ctx.save();
      this.ctx.translate(c.x, c.y);
      const now = Date.now();
      this.ctx.rotate(now * 0.0008);
      for (let r = 0; r < 12; r++) {
        const ra = (r * Math.PI * 2) / 12;
        this.ctx.fillStyle = (r % 2 === 0) ? "rgba(255, 215, 0, 0.12)" : "rgba(255, 255, 255, 0.07)";
        this.ctx.beginPath();
        this.ctx.moveTo(0, 0);
        this.ctx.lineTo(Math.cos(ra - 0.14) * 400, Math.sin(ra - 0.14) * 400);
        this.ctx.lineTo(Math.cos(ra + 0.14) * 400, Math.sin(ra + 0.14) * 400);
        this.ctx.closePath();
        this.ctx.fill();
      }
      this.ctx.restore();
    }

    // 7. Ekran Ortası Duyuru Başlığı
    if (this.floatingBanner) {
      this.drawFloatingBanner();
    }

    this.ctx.restore();
  }

  drawTowerBackground() {
    const minY = this.cameraY - 120;
    const maxY = this.cameraY + CONFIG.CANVAS_HEIGHT + 120;

    // Derin Velvet Obsidian Gradyanı
    const curSpec = CONFIG.FLOORS[this.currentFloor - 1] || CONFIG.FLOORS[0];
    const bgGrad = this.ctx.createLinearGradient(0, minY, 0, maxY);
    bgGrad.addColorStop(0, curSpec.wallColor || CONFIG.COLORS.BG_DARK);
    bgGrad.addColorStop(0.5, CONFIG.COLORS.BG_MID);
    bgGrad.addColorStop(1, CONFIG.COLORS.BG_LIGHT);
    this.ctx.fillStyle = bgGrad;
    this.ctx.fillRect(0, minY, CONFIG.CANVAS_WIDTH, maxY - minY);

    // 1. Ambient Cyber Star Dust (Elite Derinlik & Parallax Efekti)
    if (this.ambientStars && this.ambientStars.length) {
      this.ctx.save();
      this.ambientStars.forEach(s => {
        if (s.y > minY && s.y < maxY) {
          this.ctx.fillStyle = `rgba(0, 255, 157, ${s.alpha})`;
          this.ctx.beginPath();
          this.ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
          this.ctx.fill();
        }
      });
      this.ctx.restore();
    }

    // 2. Zarif Mimari Dikey Çizgiler & İnce Kılavuz Ticks
    this.ctx.save();
    this.ctx.strokeStyle = "rgba(255, 255, 255, 0.04)";
    this.ctx.lineWidth = 1;
    [50, 225, 400].forEach(lx => {
      this.ctx.beginPath();
      this.ctx.moveTo(lx, minY);
      this.ctx.lineTo(lx, maxY);
      this.ctx.stroke();
    });

    // 3. P1: Kule Katları Arka Plan Çeşitliliği (Her Kat İçin Özgün Mimari Silüetler)
    CONFIG.FLOORS.forEach((floor, idx) => {
      const fy = CONFIG.DOOR_Y - idx * CONFIG.FLOOR_HEIGHT;
      if (fy > minY - 260 && fy < maxY + 260) {
        this.drawStageSpecificAtmosphere(floor.id, fy, minY, maxY);

        // Arka Plandaki Minimalist Kat Numaraları (Stencil Wall Art)
        this.ctx.font = "900 88px -apple-system, sans-serif";
        this.ctx.fillStyle = "rgba(255, 255, 255, 0.028)";
        this.ctx.textAlign = "center";
        this.ctx.fillText(`0${floor.id}`, CONFIG.CANVAS_WIDTH / 2, fy + 70);
      }
    });

    this.ctx.restore();
  }

  // P1: Kat Bazlı Tematik Arka Plan Atmosferleri
  drawStageSpecificAtmosphere(floorId, fy, minY, maxY) {
    this.ctx.save();
    const curSpec = CONFIG.FLOORS[floorId - 1] || CONFIG.FLOORS[0];

    if (floorId === 1) {
      // Kat 1: BASEMENT ENTRY — Eski Endüstriyel Bodrum Boruları & Loş Fener Halesi
      this.ctx.strokeStyle = "rgba(0, 255, 136, 0.045)";
      this.ctx.lineWidth = 6;
      this.ctx.beginPath();
      this.ctx.moveTo(0, fy + 120);
      this.ctx.lineTo(CONFIG.CANVAS_WIDTH, fy + 120);
      this.ctx.stroke();
      this.ctx.fillStyle = "rgba(0, 255, 136, 0.06)";
      [70, 210, 370].forEach(px => {
        this.ctx.fillRect(px - 4, fy + 114, 8, 12);
      });
      this.ctx.lineWidth = 4;
      this.ctx.beginPath();
      this.ctx.moveTo(70, fy - 60);
      this.ctx.lineTo(70, fy + 120);
      this.ctx.stroke();
      const lampGlow = this.ctx.createRadialGradient(380, fy - 20, 5, 380, fy - 20, 75);
      lampGlow.addColorStop(0, "rgba(255, 180, 50, 0.055)");
      lampGlow.addColorStop(1, "transparent");
      this.ctx.fillStyle = lampGlow;
      this.ctx.beginPath();
      this.ctx.arc(380, fy - 20, 75, 0, Math.PI * 2);
      this.ctx.fill();

    } else if (floorId === 2) {
      // Kat 2: KITCHEN VENT — Havalandırma Izgarası & Alt Kat Mutfak Işık Halesi
      this.ctx.strokeStyle = "rgba(255, 215, 0, 0.035)";
      this.ctx.lineWidth = 1.5;
      for (let x = 40; x < CONFIG.CANVAS_WIDTH; x += 36) {
        this.ctx.beginPath();
        this.ctx.moveTo(x, fy - 80);
        this.ctx.lineTo(x + 40, fy + 100);
        this.ctx.stroke();
        this.ctx.beginPath();
        this.ctx.moveTo(x + 40, fy - 80);
        this.ctx.lineTo(x, fy + 100);
        this.ctx.stroke();
      }
      this.ctx.strokeRect(30, fy - 85, CONFIG.CANVAS_WIDTH - 60, 190);
      const kitchenGlow = this.ctx.createRadialGradient(CONFIG.CANVAS_WIDTH / 2, fy + 90, 10, CONFIG.CANVAS_WIDTH / 2, fy + 90, 140);
      kitchenGlow.addColorStop(0, "rgba(255, 215, 0, 0.04)");
      kitchenGlow.addColorStop(1, "transparent");
      this.ctx.fillStyle = kitchenGlow;
      this.ctx.beginPath();
      this.ctx.arc(CONFIG.CANVAS_WIDTH / 2, fy + 90, 140, 0, Math.PI * 2);
      this.ctx.fill();

    } else if (floorId === 3) {
      // Kat 3: GUILLOTINE HALL — Yüksek Voltaj Lazer Rayları & Asılı Kablo Demetleri
      this.ctx.strokeStyle = "rgba(255, 0, 85, 0.055)";
      this.ctx.lineWidth = 1;
      [110, 340].forEach(rx => {
        this.ctx.beginPath();
        this.ctx.moveTo(rx, fy - 180);
        this.ctx.lineTo(rx, fy + 120);
        this.ctx.stroke();
      });
      this.ctx.strokeStyle = "rgba(255, 0, 85, 0.045)";
      this.ctx.lineWidth = 2.5;
      this.ctx.beginPath();
      this.ctx.moveTo(20, fy - 120);
      this.ctx.quadraticCurveTo(CONFIG.CANVAS_WIDTH / 2, fy - 60, CONFIG.CANVAS_WIDTH - 20, fy - 120);
      this.ctx.stroke();
      this.ctx.beginPath();
      this.ctx.moveTo(40, fy - 140);
      this.ctx.quadraticCurveTo(CONFIG.CANVAS_WIDTH / 2, fy - 90, CONFIG.CANVAS_WIDTH - 40, fy - 140);
      this.ctx.stroke();

    } else if (floorId === 4) {
      // Kat 4: WINDY BALCONY — Açık Fırtınalı Balkon, Uzak Şehir Silüeti & Korkuluklar
      this.ctx.fillStyle = "rgba(0, 229, 255, 0.025)";
      const buildings = [
        { x: 30, w: 50, h: 140 },
        { x: 90, w: 40, h: 180 },
        { x: 140, w: 60, h: 120 },
        { x: 260, w: 45, h: 160 },
        { x: 315, w: 55, h: 130 },
        { x: 380, w: 40, h: 190 }
      ];
      buildings.forEach(b => {
        this.ctx.fillRect(b.x, fy + 120 - b.h, b.w, b.h);
      });
      this.ctx.strokeStyle = "rgba(0, 229, 255, 0.05)";
      this.ctx.lineWidth = 2;
      this.ctx.beginPath();
      this.ctx.moveTo(20, fy + 65);
      this.ctx.lineTo(CONFIG.CANVAS_WIDTH - 20, fy + 65);
      this.ctx.stroke();
      for (let bx = 30; bx < CONFIG.CANVAS_WIDTH - 20; bx += 24) {
        this.ctx.beginPath();
        this.ctx.moveTo(bx, fy + 65);
        this.ctx.lineTo(bx, fy + 120);
        this.ctx.stroke();
      }

    } else if (floorId === 5) {
      // Kat 5: ROYAL ROOF — Kraliyet Çatısı, Burçlar & Parlayan Hilal Ay
      this.ctx.fillStyle = "rgba(255, 215, 0, 0.035)";
      for (let mx = 30; mx < CONFIG.CANVAS_WIDTH - 30; mx += 50) {
        this.ctx.fillRect(mx, fy + 70, 30, 45);
      }
      this.ctx.fillRect(20, fy + 115, CONFIG.CANVAS_WIDTH - 40, 15);
      const moonX = 350;
      const moonY = fy - 120;
      const moonGlow = this.ctx.createRadialGradient(moonX, moonY, 10, moonX, moonY, 70);
      moonGlow.addColorStop(0, "rgba(255, 215, 0, 0.08)");
      moonGlow.addColorStop(1, "transparent");
      this.ctx.fillStyle = moonGlow;
      this.ctx.beginPath();
      this.ctx.arc(moonX, moonY, 70, 0, Math.PI * 2);
      this.ctx.fill();

      this.ctx.fillStyle = "rgba(255, 240, 180, 0.12)";
      this.ctx.beginPath();
      this.ctx.arc(moonX, moonY, 26, 0, Math.PI * 2);
      this.ctx.fill();
      this.ctx.fillStyle = curSpec.wallColor || "#100a1d";
      this.ctx.beginPath();
      this.ctx.arc(moonX - 9, moonY - 7, 24, 0, Math.PI * 2);
      this.ctx.fill();

      this.ctx.font = "32px -apple-system, sans-serif";
      this.ctx.fillStyle = "rgba(255, 215, 0, 0.055)";
      this.ctx.textAlign = "center";
      this.ctx.fillText("👑", CONFIG.CANVAS_WIDTH / 2, fy - 65);
    }
    this.ctx.restore();
  }

  // İlk 2 Saniye Kancası: Sadeleştirilmiş Sapan İpucu
  drawLaunchTutorialPrompt() {
    this.ctx.save();
    const cx = this.cat.startX;
    const cy = this.cat.startY + 62;
    const bounce = Math.sin(Date.now() * 0.006) * 5;

    this.ctx.fillStyle = "rgba(14, 10, 24, 0.88)";
    this.ctx.strokeStyle = "rgba(0, 255, 136, 0.5)";
    this.ctx.lineWidth = 1.5;
    this.ctx.shadowColor = "#00ff88";
    this.ctx.shadowBlur = 10;
    this.ctx.beginPath();
    if (this.ctx.roundRect) {
      this.ctx.roundRect(cx - 85, cy - 12 + bounce, 170, 24, 12);
    } else {
      this.ctx.rect(cx - 85, cy - 12 + bounce, 170, 24);
    }
    this.ctx.fill();
    this.ctx.stroke();

    this.ctx.font = "800 11px -apple-system, sans-serif";
    this.ctx.fillStyle = "#ffffff";
    this.ctx.shadowBlur = 0;
    this.ctx.textAlign = "center";
    this.ctx.fillText("👇 PULL & RELEASE", cx, cy + 4 + bounce);

    this.ctx.restore();
  }

  drawFloatingBanner() {
    if (!this.floatingBanner) return;
    this.ctx.save();
    const bx = CONFIG.CANVAS_WIDTH / 2;
    const by = this.cameraY + 220;
    this.ctx.translate(bx, by);
    this.ctx.globalAlpha = Math.max(0, this.floatingBanner.alpha);

    // Elite Frosted Glass Capsule
    this.ctx.fillStyle = "rgba(12, 8, 22, 0.90)";
    this.ctx.strokeStyle = this.floatingBanner.color;
    this.ctx.lineWidth = 1.8;
    this.ctx.shadowColor = this.floatingBanner.color;
    this.ctx.shadowBlur = 16;
    this.ctx.beginPath();
    this.ctx.roundRect ? this.ctx.roundRect(-150, -28, 300, 56, 16) : this.ctx.rect(-150, -28, 300, 56);
    this.ctx.fill();
    this.ctx.stroke();

    // Üst İnce Işıltı Hattı
    this.ctx.strokeStyle = "rgba(255, 255, 255, 0.16)";
    this.ctx.lineWidth = 1;
    this.ctx.shadowBlur = 0;
    this.ctx.beginPath();
    this.ctx.moveTo(-125, -27);
    this.ctx.lineTo(125, -27);
    this.ctx.stroke();

    // Başlık
    this.ctx.font = "900 15px -apple-system, sans-serif";
    this.ctx.fillStyle = this.floatingBanner.color;
    this.ctx.textAlign = "center";
    this.ctx.fillText(this.floatingBanner.title, 0, -4);

    // Alt Başlık
    this.ctx.font = "700 11px -apple-system, sans-serif";
    this.ctx.fillStyle = "rgba(255, 255, 255, 0.85)";
    this.ctx.fillText(this.floatingBanner.subtitle, 0, 16);

    this.ctx.restore();
  }

  drawNearMissBadge(bx, by) {
    this.ctx.save();
    this.ctx.translate(bx, by);

    this.ctx.fillStyle = "rgba(10, 10, 26, 0.95)";
    this.ctx.strokeStyle = "#ffff00";
    this.ctx.lineWidth = 2.5;
    this.ctx.shadowColor = "#ffff00";
    this.ctx.shadowBlur = 20;
    this.ctx.beginPath();
    this.ctx.roundRect ? this.ctx.roundRect(-94, -18, 188, 36, 8) : this.ctx.rect(-94, -18, 188, 36);
    this.ctx.fill();
    this.ctx.stroke();

    // Milimetre Cetvel Çizgileri
    this.ctx.strokeStyle = "#ffff00";
    this.ctx.lineWidth = 1.8;
    for (let i = -82; i <= -52; i += 4) {
      this.ctx.beginPath(); this.ctx.moveTo(i, -10); this.ctx.lineTo(i, i % 8 === 0 ? 6 : -2); this.ctx.stroke();
    }
    for (let i = 52; i <= 82; i += 4) {
      this.ctx.beginPath(); this.ctx.moveTo(i, -10); this.ctx.lineTo(i, i % 8 === 0 ? 6 : -2); this.ctx.stroke();
    }

    this.ctx.font = "900 13px -apple-system, sans-serif";
    this.ctx.fillStyle = "#ffff00";
    this.ctx.textAlign = "center";
    this.ctx.fillText("⚡ 1 MILLIMETER! ⚡", 0, 5);

    // Küçük Ok
    this.ctx.fillStyle = "#ffff00";
    this.ctx.shadowBlur = 12;
    this.ctx.beginPath();
    this.ctx.moveTo(-7, 18); this.ctx.lineTo(7, 18); this.ctx.lineTo(0, 26);
    this.ctx.closePath();
    this.ctx.fill();

    this.ctx.restore();
  }

  loop(currentTime) {
    const now = (typeof currentTime === "number" && !isNaN(currentTime)) ? currentTime : (typeof performance !== "undefined" && performance.now ? performance.now() : Date.now());
    const rawDt = this.lastTime ? (now - this.lastTime) / 1000 : 0.016;
    this.lastTime = now;
    const dt = Math.min(Math.max(0.001, rawDt || 0.016), 0.033);
    this.update(dt);
    this.render();
    requestAnimationFrame(this.loop);
  }
}

window.addEventListener("DOMContentLoaded", () => {
  window.game = new GameEngine();
});


